  if (/podcast|interview|entrevista|reaction|reacci[oó]n|vlog|gameplay|walkthrough|playthrough|streamer|face.?cam|talking\s+head|presentador|presenter|hosted by|music video|video oficial|lyrics|lyric video|vevo|news|noticias|breaking|trailer|teaser/i.test(lower)) return false;
