  if (/[äöüß]/i.test(raw)) strongScores.de += 2.5;
  if (/[àâçéèêëîïôûùüÿœ]/i.test(raw)) strongScores.fr += 2;
  if (/[ãõ]/i.test(raw)) strongScores.pt += 2.5;
  if (/[ñ¿¡áéíóú]/i.test(raw)) strongScores.es += 2;
