    es: (raw.match(/\b(el|la|los|las|con|para|historia|mitologia|supervivencia|finanzas|misterio|relato|cuentos)\b/g) || []).length + (/[áéíóúñ¿¡]/i.test(raw) ? 2 : 0),
    fr: (raw.match(/\b(le|la|les|des|avec|histoire|mythologie|documentaire|mystere|finance)\b/g) || []).length + (/[àâçéèêëîïôûùüÿœ]/i.test(raw) ? 2 : 0),
    de: (raw.match(/\b(der|die|das|und|mit|geschichte|mythologie|dokumentation|finanzen|geheimnisse)\b/g) || []).length + (/[äöüß]/i.test(raw) ? 2 : 0),
    pt: (raw.match(/\b(o|a|os|as|com|para|historia|mitologia|documentario|financas|misterios)\b/g) || []).length + (/[ãõç]/i.test(raw) ? 2 : 0),
    it: (raw.match(/\b(il|lo|la|gli|con|per|storia|mitologia|documentario|finanza|misteri)\b/g) || []).length,
    pl: (folded.match(/\b(historia|tajemnice|psychologia|nauka|przetrwanie|ktory|ktora|ktore|ludzkosc|powierzchni|ziemi|wulkan)\b/g) || []).length + (/[ąćęłńóśźż]/i.test(raw) ? 2 : 0),
    ro: (raw.match(/\b(si|cu|pentru|istorie|mitologie|documentar|finante|mistere)\b/g) || []).length + (/[ăâîșşțţ]/i.test(raw) ? 2 : 0),
