function getAshlyVNoRecycleSeriesKey(item) {
  var sc = (item && item.sc) || {};
  var title = getAshlyVNormalizedTitleBase(sc.title || item && item.title || '');
  var channel = normalizeChannelNameKey(sc.channelName || sc.channelHandle || item && item.channelName || '') ||
    String(sc.channelKey || sc.channelUrl || item && item.channelId || '').toLowerCase().trim();
  var series = '';
  if (/\byour life as\b/.test(title) || /\bevery rank in\b/.test(title)) series = 'your-life-as-every-rank';
  else if (/\ball of\b.*\bexplained\b/.test(title)) series = 'all-of-explained';
  else if (/\biceberg\b/.test(title)) series = 'iceberg';
  else if (/\b(?:misterios?|mysteries|secretos?|secrets?)\b/.test(title) && /\b(?:explicad|explained|documental|documentary)\b/.test(title)) series = 'mystery-explained';
  else if (/\b(?:fall asleep|sleep|dormir)\b/.test(title) && /\b(?:history|historia)\b/.test(title)) series = 'sleep-history';
  else if (/\b(?:top|ranking|countdown)\b/.test(title)) series = 'top-ranking';
  if (series) return 'series:' + series;
  var words = title.split(/\s+/).filter(function(word) {
    return word && word.length >= 5 && !ASHLYV_TOPIC_STOPWORDS[word] && !/every|rank|explained|explicado|explicada|historia|history|documentary|documental|misterio|misterios|secretos|video/.test(word);
  }).slice(0, 3).join('-');
  if (channel && words) return 'channel-topic:' + channel + '::' + words;
  return words ? ('topic:' + words) : '';
}

function filterAshlyVNoRecycleFeedDiversity(items, target) {
  target = Math.max(1, Number(target || 10));
  var source = dedupeAshlyVResults(items || []);
  var picked = [];
  var usedVideo = {};
  var usedTitle = {};
  var usedChannel = {};
  var usedSeries = {};

  function add(item) {
    if (!item || picked.length >= target) return;
    var sc = (item && item.sc) || {};
    var videoKey = getAshlyVDedupeKeyFromSc(sc, item) || getAshlyVResultKey(item);
    var titleKey = getAshlyVNormalizedTitleBase(sc.title || item.title || '');
    var channelKey = normalizeChannelNameKey(sc.channelName || sc.channelHandle || item.channelName || '') ||
      String(sc.channelKey || sc.channelUrl || item.channelId || '').toLowerCase().trim();
    var seriesKey = getAshlyVNoRecycleSeriesKey(item);
    if (videoKey && usedVideo[videoKey]) return;
    if (titleKey && usedTitle[titleKey]) return;
    if (channelKey && usedChannel[channelKey]) return;
    if (seriesKey && usedSeries[seriesKey]) return;
    picked.push(normalizeAshlyVGuaranteedFacelessResult(item));
    if (videoKey) usedVideo[videoKey] = true;
    if (titleKey) usedTitle[titleKey] = true;
    if (channelKey) usedChannel[channelKey] = true;
    if (seriesKey) usedSeries[seriesKey] = true;
  }

  source.forEach(add);
  return picked.slice(0, target);
}

var ASHLYV_STABLE_NO_RECYCLE_KEY = 'ashlyv_stable_no_recycle_v1';
var ASHLYV_STABLE_NO_RECYCLE_MAX = 1800;

function getAshlyVStableChannelKey(item) {
  var sc = (item && item.sc) || {};
  var raw = sc.channelKey || sc.channelId || item && item.channelId || sc.channelUrl || sc.channelHandle || sc.channelName || item && item.channelName || '';
  raw = String(raw || '').trim().toLowerCase();
  if (!raw) return '';
  if (/^https?:\/\//.test(raw)) raw = raw.split('?')[0].replace(/\/+$/, '');
  return raw.indexOf('name:') === 0 || raw.indexOf('id:') === 0 || raw.indexOf('handle:') === 0 || raw.indexOf('url:') === 0
    ? raw
    : 'channel:' + normalizeChannelNameKey(raw);
}

function getAshlyVStableNoRecycleKey(item) {
  var sc = (item && item.sc) || {};
  var videoKey = getAshlyVDedupeKeyFromSc(sc, item) || getAshlyVResultKey(item);
  var titleKey = getAshlyVNormalizedTitleBase(sc.title || item && item.title || '');
  var channelKey = getAshlyVStableChannelKey(item);
  var topicKey = sc ? getAshlyVTopicKey(sc) : '';
  var seriesKey = getAshlyVNoRecycleSeriesKey(item);
  return {
    videoKey: videoKey || '',
    titleKey: titleKey || '',
    channelKey: channelKey || '',
    topicKey: topicKey || '',
    seriesKey: seriesKey || '',
    familyKey: channelKey && seriesKey ? channelKey + '::' + seriesKey : (seriesKey || titleKey || '')
  };
}

function readAshlyVStableNoRecycleHistory() {
  try {
    var raw = localStorage.getItem(ASHLYV_STABLE_NO_RECYCLE_KEY);
    var data = raw ? JSON.parse(raw) : {};
    return {
      videoKeys: Array.isArray(data.videoKeys) ? data.videoKeys : [],
      titleKeys: Array.isArray(data.titleKeys) ? data.titleKeys : [],
      channelKeys: Array.isArray(data.channelKeys) ? data.channelKeys : [],
      topicKeys: Array.isArray(data.topicKeys) ? data.topicKeys : [],
      familyKeys: Array.isArray(data.familyKeys) ? data.familyKeys : []
    };
  } catch(e) {
    return { videoKeys: [], titleKeys: [], channelKeys: [], topicKeys: [], familyKeys: [] };
  }
}

function writeAshlyVStableNoRecycleHistory(data) {
  try {
    ['videoKeys', 'titleKeys', 'channelKeys', 'topicKeys', 'familyKeys'].forEach(function(key) {
      data[key] = Array.from(new Set((data[key] || []).filter(Boolean))).slice(0, ASHLYV_STABLE_NO_RECYCLE_MAX);
    });
    localStorage.setItem(ASHLYV_STABLE_NO_RECYCLE_KEY, JSON.stringify(data));
  } catch(e) {}
}

function clearAshlyVStableNoRecycleHistory() {
  try { localStorage.removeItem(ASHLYV_STABLE_NO_RECYCLE_KEY); } catch(e) {}
}

function isAshlyVStableNoRecycleBlocked(item) {
  var keys = getAshlyVStableNoRecycleKey(item);
  if (AshlyVRecentRuns && AshlyVRecentRuns.isBlockedItem && AshlyVRecentRuns.isBlockedItem(item)) return true;
  if (AshlyVMemory) {
    if (keys.videoKey && /^vid:/.test(keys.videoKey) && AshlyVMemory.hasSeenVideo && AshlyVMemory.hasSeenVideo(keys.videoKey.replace(/^vid:/, ''))) return true;
    if (keys.titleKey && AshlyVMemory.hasSeenTitle && AshlyVMemory.hasSeenTitle(keys.titleKey)) return true;
    if (keys.channelKey && AshlyVMemory.hasSeenChannelKey && AshlyVMemory.hasSeenChannelKey(keys.channelKey)) return true;
  }
  var hist = readAshlyVStableNoRecycleHistory();
  if (keys.videoKey && hist.videoKeys.indexOf(keys.videoKey) !== -1) return true;
  if (keys.titleKey && hist.titleKeys.indexOf(keys.titleKey) !== -1) return true;
  if (keys.channelKey && hist.channelKeys.indexOf(keys.channelKey) !== -1) return true;
  if (keys.familyKey && hist.familyKeys.indexOf(keys.familyKey) !== -1) return true;
  return false;
}

function isAshlyVPanelFillNoRecycleBlocked(item) {
  // Passive scan history cannot block panel fill; otherwise repeated SCAN tests
  // consume valid niches and the user sees 0. Current-panel duplicates are
  // handled by filterAshlyVPanelNicheDiverseResults().
  return !item;
}

function markAshlyVStableNoRecycleSeen(items) {
  var hist = readAshlyVStableNoRecycleHistory();
  (items || []).forEach(function(item) {
    var keys = getAshlyVStableNoRecycleKey(item);
    if (keys.videoKey) hist.videoKeys.unshift(keys.videoKey);
    if (keys.titleKey) hist.titleKeys.unshift(keys.titleKey);
    if (keys.channelKey) hist.channelKeys.unshift(keys.channelKey);
    if (keys.familyKey) hist.familyKeys.unshift(keys.familyKey);
  });
  writeAshlyVStableNoRecycleHistory(hist);
}

function scoreAshlyVStableHomeFacelessCandidate(item) {
  var sc = (item && item.sc) || {};
  var profile = getAshlyVGenerativeAiProfile(item);
  var analysis = item && item._facelessAnalysis || {};
  var score = 0;
  if (!isAshlyVAiFacelessEconomicallyViable(item)) return -9999;
  var apiHighIntent = typeof nspIsHighIntentApiFacelessCandidate === 'function' && nspIsHighIntentApiFacelessCandidate(item);
  if (isAshlyVTargetAiFacelessCandidate(item)) score += 100;
  else if (apiHighIntent) score += 92;
  else if (isAshlyVHomeFeedFacelessRescueCandidate(item)) score += 72;
  else if (typeof isAshlyVFeedSafeFacelessCandidate === 'function' && isAshlyVFeedSafeFacelessCandidate(item)) score += 62;
  else if (typeof isAshlyVFeedReplicableFallbackCandidate === 'function' && isAshlyVFeedReplicableFallbackCandidate(item)) score += 48;
  else return -9999;
  score += Math.min(100, Number(profile && profile.score || 0)) * 6;
  score += Math.min(100, Number(analysis.facelessScore || item && item._facelessScore || 0)) * 2;
  score += Math.min(800, Number(sc.vph || 0)) * 5;
  score += Math.min(500000, Number(sc.views || 0)) / 1000;
  score += Math.min(50000, Number(sc.totalRev || sc.revMonth || 0)) / 120;
  score += Math.min(100, Number(sc.os || item && item.os || 0)) * 3;
  if (NSP_AI_FACELESS_AI_STACK_SIGNAL.test((sc.title || '') + ' ' + (sc.channelName || ''))) score += 140;
  return score;
}

