function calcSeoScore(title, tags) {
  let score = 0; const t = (title || '').trim(); const words = t.split(/\s+/).length;
  if (t.length >= 40 && t.length <= 70) score += 25; else if (t.length >= 25) score += 12;
  if (words >= 7 && words <= 14) score += 20; else if (words >= 4) score += 10;
  if (/\b(202[3-9]|2030|\d{2,})\b/.test(t)) score += 10;
  if (/\b(best|top|how to|why|secret|hidden|real|true|must|only|never|always|guide|tutorial|complete|full|hours|free|easy|fast)\b/i.test(t)) score += 15;
  if (/[\u{1F300}-\u{1FFFF}]/u.test(t)) score += 5;
  if (tags && tags.length >= 5) score += 15; else if (tags && tags.length >= 1) score += 7;
  if (t.length < 15) score -= 10;
  return Math.max(0, Math.min(100, score));
}

function calculateOutlierBonus(views, subs) {
  if (!subs || subs < 100) return 0;
  var ratio = views / subs;
  if (ratio > 20) return 50;  // Ultra Outlier
  if (ratio > 10) return 30;  // Mega Outlier
  if (ratio > 5)  return 15;  // Strong Outlier
  return 0;
}

function seoLabel(score) {
  if (score >= 80) return { text: `SEO ${score}`, color: '#00e676' };
  if (score >= 55) return { text: `SEO ${score}`, color: '#ffd700' };
  if (score >= 30) return { text: `SEO ${score}`, color: '#ff9800' };
  return { text: `SEO ${score}`, color: '#ff3d00' };
}

function estimateCTR(title) {
  let ctr = 3.0; const t = (title || '').toLowerCase();
  if (/[\u{1F300}-\u{1FFFF}]/u.test(title)) ctr += 1.2;
  if (/\b(\d+)\b/.test(t)) ctr += 0.8;
  if (/\b(secret|hidden|never|only|shocking|real)\b/i.test(t)) ctr += 1.5;
  if (/\?$/.test(t.trim())) ctr += 0.5;
  if (title.length > 80) ctr -= 1.0;
  if (title.length < 20) ctr -= 0.5;
  return Math.min(12, Math.max(0.5, parseFloat(ctr.toFixed(1))));
}

function keywordCompetition(title) {
  const t = (title || '').toLowerCase();
  if (t.match(/sleep|heal|soundscape|ambient|nordic|celtic|shamanic/)) return { level: 'LOW', color: '#00e676', score: 22 };
  if (t.match(/history|ancient|war|medieval/))                         return { level: 'MED', color: '#ffd700', score: 48 };
  if (t.match(/survival|prepper|wilderness/))                          return { level: 'MED', color: '#ffd700', score: 45 };
  if (t.match(/finance|invest|crypto/))                                return { level: 'HIGH', color: '#ff3d00', score: 85 };
  if (t.match(/gaming|minecraft|fortnite/))                            return { level: 'HIGH', color: '#ff3d00', score: 90 };
  if (t.match(/motivation|self.?help|success/))                        return { level: 'HIGH', color: '#ff3d00', score: 78 };
  if (t.match(/español|historia|crimen/))                              return { level: 'MED', color: '#ffd700', score: 50 };
  return { level: 'MED', color: '#ffd700', score: 50 };
}

function velocityLabel(vph) {
  if (vph > 50000) return { text: '🚀 VIRAL',    color: '#ff3d00' };
  if (vph > 10000) return { text: '🔥 HOT',      color: '#ff9800' };
  if (vph > 2000)  return { text: '📈 RISING',   color: '#00e676' };
  if (vph > 500)   return { text: '➡️ STEADY',   color: '#66fcf1' };
  if (vph > 0)     return { text: '📉 SLOW',     color: '#aaaaaa' };
  return                  { text: '⏳ NEW',       color: '#aaaaaa' };
}

function calcScore(views, hoursOld, isShort, title, durationSecs) {
  if (!views || views < 1) return null;
  var h = (hoursOld != null && hoursOld > 0) ? hoursOld : 720;
  var vph = views / h;
  
  var t = (title || '').toLowerCase();
  // ── RPM = nicho × idioma (geo) ───────────────────────────────────────────────
  // FIX: antes el español se forzaba a 1.8 fijo (ignoraba el nicho) y los términos ES
  // daban RPM más bajos que sus equivalentes EN (doble castigo). Ahora: RPM base del
  // NICHO (bilingüe, en USD de mercado top tipo USA) × multiplicador por IDIOMA detectado.
  // 1) RPM base del nicho (keywords ES + EN juntas, mismo número para el mismo nicho)
  var baseRpm = 3.0;
  if (t.match(/sleep|relax|meditat|ambient|\brain\b|thunder|binaural|\bheal(ing)?\b|soundscape|dormir|relajar|lluvia|sonidos|ruido.?blanco|lofi/)) baseRpm = 10.0;   // FIX: heal/rain anclados (no roban health/train/brain)
  else if (t.match(/finance|invest|trading|stock|\bmarket\b|budget|wealth|dividend|portfolio|finanzas|inversion|invertir|bolsa|acciones|riqueza|ahorro|presupuesto|dinero|rico|millonario|aktien|geld|verm[öo]gen|b[öo]rse|sparen|bourse|argent|riche|patrimoine|investir|[ée]pargne/)) baseRpm = 22.0;   // FIX: \bmarket\b (no roba "marketing") + quité "reich" (era historia alemana, no finanzas)
  else if (t.match(/crypto|bitcoin|ethereum|nft|defi|blockchain|cripto|criptomoneda|krypto|kryptow[äa]hrung|crypto.?monnaie/)) baseRpm = 18.0;
  else if (t.match(/business|entrepreneur|startup|marketing|ecommerce|dropship|passive.?income|negocio|emprend|marketing|ingresos.?pasivos|ganar.?dinero|ventas|vender|monetiz|unternehmen|gesch[äa]ft|verkauf|entreprise|vente|affaires/)) baseRpm = 16.0;
  else if (t.match(/legal|law|attorney|lawsuit|court|judge|insurance|mortgage|loan|credit.?card|abogado|ley|demanda|juicio|seguro|hipoteca|prestamo|credito|recht|anwalt|gericht|versicherung|hypothek|kredit|avocat|loi|proc[èe]s|assurance|hypoth[èe]que|cr[ée]dit/)) baseRpm = 14.0;
  else if (t.match(/real.?estate|property|rent|apartment|bienes.?raices|inmueble|propiedad|alquiler|renta|immobilien|wohnung|miete|immobilier|appartement|location/)) baseRpm = 12.0;
  else if (t.match(/artificial.?intelligence|machine.?learning|chatgpt|openai|gemini|midjourney|software|coding|programming|developer|python|tech|inteligencia.?artificial|automatizacion|programacion|codigo|tecnologia|k[üu]nstliche.?intelligenz|\bki\b|programmier|technologie|intelligence.?artificielle|\bia\b|programmation|technologie/)) baseRpm = 13.0;
  else if (t.match(/luxury|billionaire|mansion|yacht|supercar|lujo|millonario|mansion|lifestyle|luxus|million[äa]r|reichtum|luxe|milliardaire|richesse/)) baseRpm = 11.0;
  // HOGAR / DIY / TRUCOS CASEROS / REPARACIÓN (moho, ducha, TV, electrodomésticos, "modo secreto"…)
  // Audiencia con casa = anunciantes de hogar/herramientas/seguros. Keywords específicas para NO robarle a gaming.
  else if (t.match(/home.?(improvement|repair|hack|tip)|how.?to.?(fix|clean|repair|unclog)|life.?hack|\bappliance|plumbing|\bmold\b|\bmould\b|clogged|\brust\b|\bleak\b|secret.?mode|hidden.?(feature|setting)|casero|caseros|del.?hogar|repar(ar|aci[oó]n|a.?tu)|arregl(ar|a.?tu)|\bmoho\b|\bgotera\b|\bfuga\b|desatasc|[oó]xido|electrodom|lavadora|nevera|refrigerador|televisor|control.?remoto|modo.?secreto|funci[oó]n.?oculta|el.?fabricante|truco.?(de|del|para|casero)|haushalt|reparieren|schimmel|fernseher|ger[äa]t|geheim(er)?.?modus|waschmaschine|k[üu]hlschrank|r[ée]parer|moisissure|astuce|t[ée]l[ée]viseur|mode.?secret/)) baseRpm = 8.0;
  else if (t.match(/health|fitness|workout|diet|nutrition|medical|salud|ejercicio|dieta|nutricion|medic|bienestar|gesundheit|ern[äa]hrung|abnehmen|sant[ée]|r[ée]gime|nutrition/)) baseRpm = 7.0;
  else if (t.match(/history|ancient|war|empire|civil|medieval|nomad|pharaoh|roman|viking|historia|antigu|imperio|guerra|civiliz|faraon|romano|vikingo|conquista|edad.?media|geschichte|krieg|reich|kaiser|antike|mittelalter|histoire|guerre|empire|antiquit[ée]|m[ée]di[ée]val/)) baseRpm = 6.0;
  else if (t.match(/science|physics|biology|chemistry|astronomy|space|universe|quantum|ciencia|fisica|biologia|quimica|astronomia|espacio|universo|planeta|cosmos|wissenschaft|physik|weltraum|universum|sterne|planet|science|physique|espace|univers|astronomie/)) baseRpm = 6.0;
  else if (t.match(/survival|prepper|wilderness|outlaw|shtf|superviv|refugio|trampa|prepar|[üu]berleben|wildnis|survie|survivre|nature.?sauvage/)) baseRpm = 5.0;
  else if (t.match(/nature|wildlife|ocean|forest|asmr|naturaleza|animales|oceano|bosque|natur|tiere|tier|ozean|wald|meer|nature|animaux|oc[ée]an|for[êe]t|conejo|kaninchen|lapin|hund|gato|katze|chat|chien|perro/)) baseRpm = 5.0;
  else if (t.match(/psychology|philosophy|stoic|motivation|success|psicologia|filosofia|estoic|motivacion|exito|mentalidad|psychologie|philosophie|erfolg|stoizismus|psychologie|philosophie|succ[èe]s|stoicisme/)) baseRpm = 5.0;
  else if (t.match(/true.?crime|paranormal|horror|creepy|conspiracy|crimen|narco|terror|paranormal|conspiracion|misterio|verbrechen|mord|geheimnis|unheimlich|crime|meurtre|myst[èe]re|effrayant/)) baseRpm = 4.5;
  else if (t.match(/cooking|recipe|food|kitchen|cocina|receta|comida|gastronom|kochen|rezept|essen|k[üu]che|cuisine|recette|nourriture/)) baseRpm = 4.0;
  else if (t.match(/\bships?\b|\bboats?\b|titanic|\bnavy\b|barco|naufragio|buque|schiff|\bboote?\b|submarine|submarino|navire|bateau|naufrage/)) baseRpm = 4.0;   // FIX: ship/boat/boot anclados (no roban friendship/relationship/championship/reboot)
  else if (t.match(/gaming|minecraft|roblox|fortnite|gameplay|gta|videojuego|juego|spiel|videospiel|jeu.?vid[ée]o/)) baseRpm = 3.5;
  else if (t.match(/vlog|challenge|prank|reaction|meme|funny|reto|reaccion|gracioso/)) baseRpm = 2.5;

  // 2) Multiplicador por IDIOMA / geo (USA/UK ≈ tope; Alemania/Europa alto; español medio)
  var rpmGeo = 0.75, gl;   // default neutro si no hay señal clara
  // FIX idioma: quitados tokens ES que colisionaban con inglés (son/un/de/la/los/las/por/este).
  // Alemán/francés reforzados con palabras de CONTENIDO (doku, krieg, biografie…) para no caer al default 0.75.
  if (/[ñ¿¡]|\b(cómo|por qué|porque|qué|años|año|niños|según|español|cuánto|gratis|dinero|cuál|quién|nunca|nuevo|nueva|mejores|secreto|así|también|aquí|cosas|hizo|tienen|estaban)\b/.test(t)) { rpmGeo = 0.48; gl = 'es'; }
  else if (/[ßäöü]|\b(der|die|das|und|wie|warum|geschichte|jahre?|welt|deutsch|nicht|über|für|sind|wird|doku|dokumentation|krieg|leben|geheimnis|biografie|entdeckung|gr[öo][sß]te|wahrheit|warum)\b/.test(t)) { rpmGeo = 0.95; gl = 'de'; }
  else if (/[àâçéèêëîïôûù]|\b(le|les|une|des|pourquoi|comment|histoire|monde|ans|français|c'est|n'est|être|plus|guerre|documentaire|vie|secret|v[ée]rit[ée]|d[ée]couverte)\b/.test(t)) { rpmGeo = 0.78; gl = 'fr'; }
  else if (/[ãõ]|\b(você|não|são|português|história|mundo|anos|porque|muito|grátis|dinheiro|segredo|verdade)\b/.test(t)) { rpmGeo = 0.45; gl = 'pt'; }
  else if (/\b(the|how|why|what|of|and|years|history|world|free|money|best|top|this|that|with|your|secret|every|biggest)\b/.test(t)) { rpmGeo = 1.0; gl = 'en'; }
  baseRpm = baseRpm * rpmGeo;

  var isMusicSleep = t.match(/music|sleep|relax|ambient|drum|nordic|celtic|pagan|shamanic|heal|soundscape/);
  if (!isShort && !isMusicSleep && durationSecs > 0 && (durationSecs / 60) >= 8) baseRpm *= 1.2;
  
  var rpm = isShort ? 0.08 : parseFloat(baseRpm.toFixed(2));

  var tier = TIERS[TIERS.length - 1];
  for (var i = 0; i < TIERS.length; i++) { if (vph >= TIERS[i].min) { tier = TIERS[i]; break; } }
  
  // Revenue total real: views acumuladas × RPM
  var totalRev = Math.round((views * 0.95) / 1000 * rpm);

  // Revenue mes 1: reconstruir desde VPH long-tail para videos viejos
  var rev = 0;
  if (hoursOld !== null && hoursOld <= 720) {
    // Video reciente: proyectar mes completo
    var hoursLeft = 720 - hoursOld;
    var futureViews = vph * 0.25 * hoursLeft;
    rev = Math.round(((views + futureViews) * 0.95) / 1000 * rpm);
  } else {
    // Video viejo: estimar mes 1 desde VPH long-tail (~5% del pico)
    var vphPeak = vph / 0.05;
    rev = Math.round((vphPeak * 24 * 7 * 1.7) * 0.95 / 1000 * rpm);
  }
  
  // OS: VPH = 70pts, bonus frescura sin penalidad por antiguedad
  var freshBonus = (hoursOld == null) ? 20 : (hoursOld <= 168 ? 30 : hoursOld <= 720 ? 15 : hoursOld <= 1440 ? 8 : 5);
  var vphScore = Math.min(Math.log(vph + 1) / Math.log(10) / 4, 1) * 70;
  var os = Math.min(Math.round(vphScore + freshBonus), 100);
  
  return { vph: vph, tier: tier, os: os, rev: rev, totalRev: totalRev, rpm: rpm, isShort: !!isShort, title: title };
}

function fmtVPH(v) {
  if (v >= 10000) return (v / 1000).toFixed(1) + 'K';
  if (v >= 1000)  return (v / 1000).toFixed(2) + 'K';
  if (v >= 1)     return v.toFixed(1);
  return v.toFixed(3);
}
function fmtN(n) {
  if (n >= 1e9)  return (n / 1e9).toFixed(1) + 'B';
  if (n >= 1e6)  return (n / 1e6).toFixed(1) + 'M';
  if (n >= 1000) return Math.round(n / 1000) + 'K';
  return '' + n;
}

// ── Badge ────────────────────────────────────────────────────────────────────

function chip(txt, col, bg, bd) {
  var s = document.createElement('span');
  s.style.cssText = 'display:inline-flex;align-items:center;padding:2px 5px;border-radius:4px'
    + ';background:' + bg + ';border:1px solid ' + bd + ';color:' + col
    + ';font-size:9.5px;font-weight:700;letter-spacing:.02em;white-space:nowrap;line-height:1.2;'
    + 'box-shadow:inset 0 1px 0 rgba(255,255,255,.05),0 0 12px rgba(255,255,255,.03);text-shadow:0 0 8px rgba(255,255,255,.08);';
  s.textContent = txt;
  return s;
}

function monoBadgeChip(txt, strong) {
  return chip(
    txt,
    '#FFFFFF',
    strong ? 'linear-gradient(135deg,rgba(255,255,255,.14),rgba(0,0,0,.92))' : 'linear-gradient(135deg,rgba(255,255,255,.08),rgba(0,0,0,.95))',
    strong ? 'rgba(255,255,255,.24)' : 'rgba(255,255,255,.13)'
  );
}

// One-time CSS injection for compact hover-expandable badge
function ensureNspBadgeStyles() {
  if (document.getElementById('nsp-badge-styles')) return;
  var s = document.createElement('style');
  s.id = 'nsp-badge-styles';
  s.textContent =
    '.nsp-badge { display:flex; flex-direction:column; gap:3px; padding:4px 0; font-family:ui-monospace,monospace; position:relative; z-index:9000; margin-bottom:6px; }' +
    '.nsp-badge-summary { display:flex; flex-wrap:wrap; align-items:center; gap:3px; cursor:pointer; transition:opacity .15s; }' +
    '.nsp-badge:hover .nsp-badge-summary { opacity:.35; }' +
    '.nsp-badge-detail { display:none; flex-direction:column; gap:3px; position:absolute; top:100%; left:0; right:0; background:rgba(0,0,0,.95); border:1px solid rgba(255,255,255,.15); border-radius:6px; padding:6px; box-shadow:0 4px 16px rgba(0,0,0,.6); z-index:10000; }' +
    '.nsp-badge:hover .nsp-badge-detail { display:flex; }' +
    '.nsp-badge-row { display:flex; flex-wrap:wrap; align-items:center; gap:3px; }';
  (document.head || document.documentElement).appendChild(s);
}

function makeBadge(views, sc) {
  ensureNspBadgeStyles();
  var el = document.createElement('div');
  el.className = 'nsp-badge';
  el.dataset.tier = sc.tier.key;
  el.dataset.vph = Math.round(sc.vph);
  el.dataset.os = sc.os;

  // ── Resolve outlier tier first so we can include it in summary
  if (!sc._outlierTier) {
    try {
      var _ck = sc.channelKey || sc.channelUrl;
      var _ce = _ck ? _channelMap[_ck] : null;
      if (_ce && _ce.avgViews > 0) sc._outlierTier = getChannelOutlierTier(sc.views || views, _ce.avgViews);
    } catch(e) {}
  }

  // ── SUMMARY (1 line, always visible, compact)
  var summary = document.createElement('div');
  summary.className = 'nsp-badge-summary';
  summary.title = 'Pasa el cursor para ver el detalle completo';

  if (sc.isShort) summary.appendChild(monoBadgeChip('▶', true));
  summary.appendChild(monoBadgeChip('⚡ ' + fmtVPH(sc.vph) + '/h', true));
  if (sc.totalRev > 0) {
    var fmtR = function(n) {
      if (n >= 1000) return '$' + (n / 1000).toFixed(1) + 'K';
      return '$' + Math.round(n);
    };
    summary.appendChild(monoBadgeChip(fmtR(sc.rev) + '/mo', false));
  }
  if (sc._outlierTier && sc._outlierTier.label) {
    var otS = sc._outlierTier;
    var outChipSummary = chip(
      otS.label,
      otS.color,
      'linear-gradient(135deg,rgba(255,255,255,.04),rgba(0,0,0,.92))',
      otS.color + '55'
    );
    outChipSummary.title = otS.ratio.toFixed(1) + 'x sobre baseline del canal';
    summary.appendChild(outChipSummary);
  }

  // ── DETAIL (hidden until hover)
  var detail = document.createElement('div');
  detail.className = 'nsp-badge-detail';

  var rowStyle = 'display:flex;flex-wrap:wrap;align-items:center;gap:3px;';
  var r1 = document.createElement('div'); r1.className = 'nsp-badge-row';
  var r2 = document.createElement('div'); r2.className = 'nsp-badge-row';
  var r3 = document.createElement('div'); r3.className = 'nsp-badge-row';

  if (sc.isShort) r1.appendChild(monoBadgeChip('▶ SHORT', true));
  var vel = velocityLabel(sc.vph);
  r1.appendChild(monoBadgeChip('👁 ' + fmtN(views), false));
  r1.appendChild(monoBadgeChip('⚡ ' + fmtVPH(sc.vph) + '/h', true));
  r1.appendChild(monoBadgeChip(vel.text, false));

  var seoScore = calcSeoScore(sc.title, []);
  var seo = seoLabel(seoScore);
  var ctr = estimateCTR(sc.title);
  var comp = keywordCompetition(sc.title);

  r2.appendChild(monoBadgeChip('💰 RPM $' + sc.rpm.toFixed(2), false));
  r2.appendChild(monoBadgeChip('📊 ' + seo.text, false));
  r2.appendChild(monoBadgeChip('🎯 CTR ~' + ctr + '%', false));
  r2.appendChild(monoBadgeChip('⚔️ Comp: ' + comp.level, false));

  if (sc.totalRev > 0) {
    var fmtRD = function(n) { return '$' + Math.round(n).toLocaleString('en-US'); };
    r3.appendChild(monoBadgeChip('💵 ' + fmtRD(sc.totalRev) + ' total', true));
    r3.appendChild(monoBadgeChip('📅 ' + fmtRD(sc.rev) + '/mo est.', true));
  }

  if (sc._outlierTier && sc._outlierTier.label) {
    var ot = sc._outlierTier;
    var outChip = chip(
      ot.label + ' OUTLIER',
      ot.color,
      'linear-gradient(135deg,rgba(255,255,255,.04),rgba(0,0,0,.92))',
      ot.color + '55'
    );
    outChip.title = ot.ratio.toFixed(1) + 'x sobre baseline del canal';
    r3.appendChild(outChip);
  }

  detail.appendChild(r1);
  detail.appendChild(r2);
  if (r3.hasChildNodes()) detail.appendChild(r3);

  el.appendChild(summary);
  el.appendChild(detail);

  return el;
}

// ── Data extraction ──────────────────────────────────────────────────────────

var _ytMap = null;
function getYtMap() {
  if (_ytMap) return _ytMap;
  _ytMap = {};
  try {
    if (!window.ytInitialData) return _ytMap;
    walkYt(window.ytInitialData, 0);
  } catch(e) {}
  return _ytMap;
}

function walkYt(obj, d) {
  if (d > 30 || !obj || typeof obj !== 'object') return;
  if (Array.isArray(obj)) { for (var i = 0; i < obj.length; i++) walkYt(obj[i], d + 1); return; }
  if (obj.videoRenderer) {
    var r = obj.videoRenderer;
    if (r.videoId) {
      var ownerRun = null;
      try {
        ownerRun =
          (r.ownerText && r.ownerText.runs && r.ownerText.runs[0]) ||
          (r.longBylineText && r.longBylineText.runs && r.longBylineText.runs[0]) ||
          (r.shortBylineText && r.shortBylineText.runs && r.shortBylineText.runs[0]) ||
          null;
      } catch(e) {}
      var browse = ownerRun && ownerRun.navigationEndpoint && ownerRun.navigationEndpoint.browseEndpoint;
      var chMeta = buildChannelIdentity(
        ownerRun && ownerRun.text || '',
        browse && browse.canonicalBaseUrl || '',
        browse && browse.browseId || ''
      );
      _ytMap[r.videoId] = {
        views: pViews(getText(r, ['viewCountText', 'shortViewCountText'])),
        hoursOld: pHours(getText(r, ['publishedTimeText'])),
        isShort: false,
        lengthText: getRendererLengthText(r),
        channelId: chMeta.channelId || '',
        channelUrl: chMeta.channelUrl || '',
        channelKey: chMeta.channelKey || '',
        channelName: chMeta.name || ''
      };
    }
  }
  if (obj.reelItemRenderer) {
    var rr = obj.reelItemRenderer;
    if (rr.videoId) {
      var rrOwner = null;
      try {
        rrOwner =
          (rr.ownerText && rr.ownerText.runs && rr.ownerText.runs[0]) ||
          (rr.shortBylineText && rr.shortBylineText.runs && rr.shortBylineText.runs[0]) ||
          null;
      } catch(e) {}
      var rrBrowse = rrOwner && rrOwner.navigationEndpoint && rrOwner.navigationEndpoint.browseEndpoint;
      var rrMeta = buildChannelIdentity(
        rrOwner && rrOwner.text || '',
        rrBrowse && rrBrowse.canonicalBaseUrl || '',
        rrBrowse && rrBrowse.browseId || ''
      );
      _ytMap[rr.videoId] = {
        views: pViews(getText(rr, ['viewCountText'])),
        hoursOld: null,
        isShort: true,
        channelId: rrMeta.channelId || '',
        channelUrl: rrMeta.channelUrl || '',
        channelKey: rrMeta.channelKey || '',
        channelName: rrMeta.name || ''
      };
    }
  }
  var keys = Object.keys(obj);
  for (var i = 0; i < keys.length; i++) {
    if (keys[i] === 'videoRenderer' || keys[i] === 'reelItemRenderer') continue;
    walkYt(obj[keys[i]], d + 1);
  }
}

function getVidId(card) {
  try { var d = card.data; if (d) {
    if (d.videoId) return { id: d.videoId, isShort: false };
    if (d.videoRenderer && d.videoRenderer.videoId) return { id: d.videoRenderer.videoId, isShort: false };
    if (d.reelItemRenderer && d.reelItemRenderer.videoId) return { id: d.reelItemRenderer.videoId, isShort: true };
  }} catch(e) {}
  try { var dd = card.__data__; if (dd) {
    if (dd.videoId) return { id: dd.videoId, isShort: false };
    var vr = (dd.data && dd.data.videoRenderer) || (dd.model && dd.model.videoRenderer);
    if (vr && vr.videoId) return { id: vr.videoId, isShort: false };
  }} catch(e) {}
  try {
    var a = card.querySelector('a[href*="/watch?v="]');
    if (a) { var m = (a.getAttribute('href')||'').match(/[?&]v=([^&\s#]+)/); if (m) return { id: m[1], isShort: false }; }
    var b = card.querySelector('a[href*="/shorts/"]');
    if (b) { var m2 = (b.getAttribute('href')||'').match(/\/shorts\/([^?&/\s#]+)/); if (m2) return { id: m2[1], isShort: true }; }
  } catch(e) {}
  return null;
}

function parseViewsAgeFromText(text) {
  var raw = (text || '').replace(/\s+/g, ' ').trim();
  if (!raw) return null;

  var viewMatch = raw.match(/(\d[\d.,]*\s*(?:k|m|b|mil)?\s*(?:de\s+)?(?:views?|vistas?|visualizaciones?|reproducciones?))/i);
  var ageMatch = raw.match(/((?:hace\s+)?\d+(?:[.,]\d+)?\s*(?:seconds?|secs?|segundos?|minutes?|mins?|minutos?|hours?|hrs?|horas?|days?|d[ií]as?|weeks?|wks?|semanas?|months?|mos?|meses?|years?|yrs?|a[ñn]os?|a\b)(?:\s+ago)?)/i);

  var views = viewMatch ? pViews(viewMatch[1]) : 0;
  var timeText = ageMatch ? ageMatch[1] : '';
  var hoursOld = timeText ? pHours(timeText) : null;
  if (!views) return null;
  return { views: views, hoursOld: hoursOld, timeText: timeText };
}

function parseAgeFromText(text) {
  var raw = (text || '').replace(/\s+/g, ' ').trim();
  if (!raw) return null;
  var ageMatch = raw.match(/((?:hace\s+)?\d+(?:[.,]\d+)?\s*(?:seconds?|secs?|segundos?|minutes?|mins?|minutos?|hours?|hrs?|horas?|days?|d[ií]as?|weeks?|wks?|semanas?|months?|mos?|meses?|years?|yrs?|a[ñn]os?|a\b)(?:\s+ago)?)/i);
  var timeText = ageMatch ? ageMatch[1] : '';
  var hoursOld = timeText ? pHours(timeText) : null;
  if (hoursOld == null || !isFinite(hoursOld)) return null;
  return { hoursOld: hoursOld, timeText: timeText };
}

function getRendererLengthText(renderer) {
  if (!renderer) return '';
  var direct = getText(renderer, ['lengthText']);
  if (direct) return direct;
  try {
    var overlays = renderer.thumbnailOverlays || [];
    for (var i = 0; i < overlays.length; i++) {
      var status = overlays[i] && overlays[i].thumbnailOverlayTimeStatusRenderer;
      if (!status) continue;
      var txt = getText(status, ['text']) || getText(status, ['accessibility.accessibilityData.label']);
      if (txt) return txt;
    }
  } catch(e) {}
  return '';
}

function findDurationSnippet(text) {
  var raw = String(text || '').replace(/\s+/g, ' ').trim();
  if (!raw) return '';
  var colon = raw.match(/\b\d{1,2}:\d{2}(?::\d{2})?\b/);
  if (colon) return colon[0];
  var phrase = raw.match(/\b\d+\s*(?:hours?|hrs?|hr|minutes?|mins?|min|seconds?|secs?|sec|horas?|hora|minutos?|minuto|segundos?|segundo)\b(?:[\s,.:]+\d+\s*(?:minutes?|mins?|min|seconds?|secs?|sec|minutos?|minuto|segundos?|segundo))?(?:[\s,.:]+\d+\s*(?:seconds?|secs?|sec|segundos?|segundo))?/i);
  if (phrase) return phrase[0];
  return '';
}

function getCardDurationText(card, vidInfo, preferredText) {
  var options = [];
  if (preferredText) options.push(preferredText);
  try {
    if (vidInfo && vidInfo.id && getYtMap()[vidInfo.id] && getYtMap()[vidInfo.id].lengthText) {
      options.push(getYtMap()[vidInfo.id].lengthText);
    }
  } catch(e) {}
  try {
    var durationNodes = card ? card.querySelectorAll(
      'ytd-thumbnail-overlay-time-status-renderer span, ' +
      '#text.ytd-thumbnail-overlay-time-status-renderer, ' +
      'ytd-thumbnail-overlay-time-status-renderer, ' +
      '.badge-shape-wiz__text, ' +
      '[overlay-style=\"DEFAULT\"] .badge-shape-wiz__text'
    ) : [];
    for (var i = 0; i < durationNodes.length; i++) {
      var txt = durationNodes[i] && durationNodes[i].textContent;
      if (txt) options.push(txt);
    }
  } catch(e) {}
  try {
    var ariaNodes = card ? card.querySelectorAll(
      'a#thumbnail[aria-label], a[href*=\"/watch?v=\"][aria-label], #video-title[aria-label], yt-image a[aria-label]'
    ) : [];
    for (var j = 0; j < ariaNodes.length; j++) {
      var aria = ariaNodes[j] && ariaNodes[j].getAttribute && ariaNodes[j].getAttribute('aria-label');
      if (aria) options.push(aria);
    }
  } catch(e) {}
  try {
    if (card && card.textContent) options.push(card.textContent);
  } catch(e) {}

  for (var k = 0; k < options.length; k++) {
    var snippet = findDurationSnippet(options[k]);
    if (snippet) return snippet;
  }
  return '';
}

function getVideoTitleNode(card) {
  return card.querySelector(
    '#video-title, #video-title-link, h3 a[href*="/watch?v="], a[href*="/watch?v="][title], '
    + '.yt-lockup-metadata-view-model-wiz__title a[href*="/watch?v="], .yt-lockup-view-model-wiz__title, '
    + 'a.yt-lockup-view-model-wiz__title'
  );
}

function usesChannelBadgeLayout(card) {
  if (!isChannelPage()) return false;
  try {
    if (card && card.matches && card.matches('ytd-rich-grid-media, ytd-grid-video-renderer, ytd-rich-item-renderer')) return true;
  } catch(e) {}
  return true;
}

function getBadgeInsertParent(card, titleEl, createHost) {
  if (!usesChannelBadgeLayout(card)) {
    return (titleEl && titleEl.parentNode) ? titleEl.parentNode
      : (card.querySelector('#meta') || card.querySelector('#details') || card.querySelector('#dismissible') || card);
  }

  var metaRoot = null;
  try {
    metaRoot = (titleEl && titleEl.closest && titleEl.closest('#meta')) || card.querySelector('#meta');
  } catch(e) {}
  metaRoot = metaRoot || card.querySelector('#details') || card.querySelector('#dismissible') || card;
  if (!metaRoot) return card;

  var existingHost = metaRoot.querySelector('.nsp-channel-badge-host');
  if (existingHost || !createHost) return existingHost || metaRoot;

  var host = document.createElement('div');
  host.className = 'nsp-channel-badge-host';
  host.style.cssText = 'display:flex;flex-wrap:wrap;align-items:center;gap:4px;margin:4px 0 2px;width:100%;';

  // Preferido (pagina de canal / layout lockup): pegar el host JUSTO DEBAJO de la linea de views,
  // como hermano siguiente del bloque de metadata. Es la posicion que pidio el dueno (arriba-izq).
  try {
    var metaVM = card.querySelector('yt-content-metadata-view-model');
    if (metaVM && metaVM.parentNode) {
      metaVM.parentNode.insertBefore(host, metaVM.nextSibling);
      return host;
    }
  } catch(e) {}

  try {
    var titleBlock = null;
    if (titleEl && titleEl.closest) titleBlock = titleEl.closest('h3');
    if (titleBlock && titleBlock.parentNode === metaRoot) {
      if (titleBlock.nextSibling) metaRoot.insertBefore(host, titleBlock.nextSibling);
      else metaRoot.appendChild(host);
      return host;
    }
  } catch(e) {}

  try {
    var metaLine = metaRoot.querySelector('#metadata-line, #metadata, ytd-video-meta-block, yt-content-metadata-view-model');
    if (metaLine && metaLine.parentNode === metaRoot) {
      metaRoot.insertBefore(host, metaLine);
      return host;
    }
  } catch(e) {}

  try { metaRoot.appendChild(host); } catch(e) {}
  return host;
}

function insertBadgeIntoCard(card, titleEl, badge) {
  if (!badge) return;

  if (!usesChannelBadgeLayout(card)) {
    var defaultParent = getBadgeInsertParent(card, titleEl, false);
    if (!defaultParent) return;
    try {
      if (titleEl && titleEl.parentNode) {
        titleEl.parentNode.insertBefore(badge, titleEl.nextSibling);
      } else {
        defaultParent.appendChild(badge);
      }
    } catch(e) {}
    return;
  }

  var insertParent = getBadgeInsertParent(card, titleEl, true);
  if (!insertParent) return;
  try { insertParent.appendChild(badge); } catch(e) {}
}

function getDomViews(card) {
  try {
    var ariaNode = card.querySelector('a[href*="/watch?v="][aria-label], #video-title[aria-label], #thumbnail[aria-label]');
    if (ariaNode) {
      var ariaParsed = parseViewsAgeFromText(ariaNode.getAttribute('aria-label') || '');
      if (ariaParsed) return ariaParsed;
    }
    var spans = card.querySelectorAll('span, yt-formatted-string');
    var vt = '', tt = '';
    for (var i = 0; i < spans.length; i++) {
      var t = (spans[i].textContent || '').trim();
      if (!t || t.length > 40) continue;
      if (!vt && /view|visuali|vista|reproduc/i.test(t)) { vt = t; continue; }
      if (!vt && /^\d[\d\s.,]*(K|M|B|mil)?\s*$/i.test(t)) { vt = t; continue; }
      if (!tt && /ago|hace|day|week|wk|month|mo|year|yr|hour|hr|min|d[íi]a|semana|mes|a[ñn]o/i.test(t)) tt = t;
    }
    var v = pViews(vt);
    if (v) return { views: v, hoursOld: pHours(tt), timeText: tt || '' };
    var metaNode = card.querySelector('#metadata-line, #metadata, ytd-video-meta-block, yt-content-metadata-view-model');
    var metaParsed = parseViewsAgeFromText(metaNode ? metaNode.textContent : '');
    if (metaParsed) return metaParsed;
    return parseViewsAgeFromText(card.textContent || '');
  } catch(e) { return null; }
}

function getDomAge(card) {
  try {
    var ariaNodes = card ? card.querySelectorAll('a[href*="/watch?v="][aria-label], #video-title[aria-label], #thumbnail[aria-label]') : [];
    for (var a = 0; a < ariaNodes.length; a++) {
      var ariaParsed = parseAgeFromText(ariaNodes[a].getAttribute('aria-label') || '');
      if (ariaParsed) return ariaParsed;
    }
    var spans = card ? card.querySelectorAll('span, yt-formatted-string') : [];
    for (var i = 0; i < spans.length; i++) {
      var t = (spans[i].textContent || '').trim();
      if (!t || t.length > 50) continue;
      if (/ago|hace|day|week|month|year|hour|min|hr|wk|mo|yr|d[íi]a|semana|mes|a[ñn]o/i.test(t)) {
        var parsed = parseAgeFromText(t);
        if (parsed) return parsed;
      }
    }
    var metaNode = card && card.querySelector('#metadata-line, #metadata, ytd-video-meta-block, yt-content-metadata-view-model');
    var metaParsed = parseAgeFromText(metaNode ? metaNode.textContent : '');
    if (metaParsed) return metaParsed;
    return parseAgeFromText(card && card.textContent || '');
  } catch(e) {
    return null;
  }
}

function getDomSubs(card) {
  try {
    var spans = card.querySelectorAll('span, yt-formatted-string, #metadata-line span');
    for (var i = 0; i < spans.length; i++) {
      var t = (spans[i].textContent || '').trim();
      if (/subscrib|suscript|seguidor/i.test(t)) return pSubs(t);
    }
    return 0;
  } catch(e) { return 0; }
}

// ── Session tracking (for popup) ─────────────────────────────────────────────

var _session = { analyzed: 0, query: '', topVideos: [] };

function trackVideo(vid, title, views, sc) {
  _session.analyzed++;
  _session.topVideos.push({ videoId: vid, title: title, views: views, vph: sc.vph, tier: sc.tier.key, os: sc.os, rev: sc.rev });
  _session.topVideos.sort(function(a, b) { return b.os - a.os; });
  if (_session.topVideos.length > 30) _session.topVideos.length = 30;
  try {
    localStorage.setItem('nsp_session', JSON.stringify({
      analyzed: _session.analyzed,
      query: _session.query,
      topVideos: _session.topVideos.slice(0, 20),
    }));
  } catch(e) {}
}

// ── Channel Scout ─────────────────────────────────────────────────────────────

var _channelMap = {};
var _scoutTimer = null;

function getChannelFromCard(card, vidInfo) {
  try {
    var ytEntry = null;
    if (vidInfo && vidInfo.id) ytEntry = getYtMap()[vidInfo.id];
    if (!ytEntry) {
      var detected = getVidId(card);
      if (detected && detected.id) ytEntry = getYtMap()[detected.id];
    }

    var link = card.querySelector(
      '#channel-name a, ytd-channel-name a, #owner-name a, .ytd-channel-name a, '
      + '.yt-content-metadata-view-model-wiz__author a, yt-content-metadata-view-model a[href^="/@"], '
      + 'a[href^="/@"], a[href*="/channel/"], a[href*="/c/"], a[href*="/user/"]'
    );
    var nameEl = link || card.querySelector('#channel-name, ytd-channel-name, #owner-name, #byline-container, #text-container, .yt-content-metadata-view-model-wiz__author');
    var name = nameEl ? (nameEl.textContent || '').trim() : '';
    var href = link ? (link.getAttribute('href') || '') : '';
    var identity = buildChannelIdentity(
      name || (ytEntry && ytEntry.channelName) || '',
      href || (ytEntry && ytEntry.channelUrl) || '',
      ytEntry && ytEntry.channelId || ''
    );

    if (!identity.channelKey && !identity.channelUrl && !identity.name) return null;
    var img = card.querySelector('#avatar img, #author-thumbnail img');
    var avatarUrl = img ? (img.getAttribute('src') || '') : '';
    identity.avatarUrl = avatarUrl;
    return identity;
  } catch(e) { return null; }
}

function updateChannelMap(chInfo, sc) {
  if (!chInfo || (!chInfo.channelKey && !chInfo.channelUrl) || !chInfo.name) return;
  var key = chInfo.channelKey || chInfo.channelUrl;
  if (!_channelMap[key]) {
    _channelMap[key] = {
      name: chInfo.name, channelUrl: chInfo.channelUrl || '', channelKey: chInfo.channelKey || '', avatarUrl: chInfo.avatarUrl || '',
      totalOS: 0, totalVPH: 0, totalViews: 0, vids: 0, topVPH: 0, topTier: 'SLOW', topViews: 0,
      outlierCounts: { mega: 0, strong: 0, good: 0 },
      rpm: sc.rpm, query: _session.query || '', detectedAt: Date.now(),
    };
  }
  var ch = _channelMap[key];
  if (chInfo.avatarUrl && !ch.avatarUrl) ch.avatarUrl = chInfo.avatarUrl;
  ch.totalOS += sc.os; ch.totalVPH += sc.vph; ch.totalViews += (sc.views || 0); ch.vids++;
  ch.avgOS = Math.round(ch.totalOS / ch.vids);
  ch.avgVPH = Math.round(ch.totalVPH / ch.vids);
  ch.avgViews = Math.round(ch.totalViews / ch.vids);
  if (sc.vph > ch.topVPH) { ch.topVPH = sc.vph; ch.topTier = sc.tier.key; }
  if ((sc.views || 0) > ch.topViews) ch.topViews = sc.views;
  if (sc.rpm > ch.rpm) ch.rpm = sc.rpm;
  // Accumulate channel-outlier tiers (views vs avgChannelViews)
  if (ch.avgViews > 0 && sc.views > 0) {
    var ratio = sc.views / ch.avgViews;
    if (ratio >= 20) ch.outlierCounts.mega++;
    else if (ratio >= 10) ch.outlierCounts.strong++;
    else if (ratio >= 5) ch.outlierCounts.good++;
  }
  clearTimeout(_scoutTimer);
  _scoutTimer = setTimeout(saveChannelScout, 1500);
}

// Channel-outlier scoring: how viral was THIS video vs the channel's own baseline.
// Returns { ratio, tier, label, color } or null if no baseline yet.
function getChannelOutlierTier(views, channelAvgViews) {
  if (!views || !channelAvgViews || channelAvgViews < 100) return null;
  var ratio = views / channelAvgViews;
  if (ratio >= 100) return { ratio: ratio, tier: 'GIGA', label: '💎 100x', color: '#E040FF' };
  if (ratio >= 20)  return { ratio: ratio, tier: 'MEGA', label: '💎 ' + Math.round(ratio) + 'x', color: '#E040FF' };
  if (ratio >= 10)  return { ratio: ratio, tier: 'STRONG', label: '🔥 ' + Math.round(ratio) + 'x', color: '#FF6B35' };
  if (ratio >= 5)   return { ratio: ratio, tier: 'GOOD', label: '⚡ ' + ratio.toFixed(1) + 'x', color: '#FFD700' };
  if (ratio >= 2)   return { ratio: ratio, tier: 'ABOVE', label: '↑ ' + ratio.toFixed(1) + 'x', color: '#00DC82' };
  return null; // do not show below 2x to avoid badge spam
}

// Get outlier stats for a known channelKey; returns null if we don't have ≥3 samples.
function getChannelOutlierStats(channelKey) {
  if (!channelKey) return null;
  var ch = _channelMap[channelKey];
  if (!ch || (ch.vids || 0) < 3) return null;
  var hot = (ch.outlierCounts && (ch.outlierCounts.mega + ch.outlierCounts.strong + ch.outlierCounts.good)) || 0;
  return {
    sampleSize: ch.vids,
    avgViews: ch.avgViews || 0,
    topViews: ch.topViews || 0,
    outlierRatio: ch.topViews && ch.avgViews ? (ch.topViews / ch.avgViews) : 0,
    outliersFound: hot,
    outlierPct: ch.vids ? Math.round((hot / ch.vids) * 100) : 0,
    mega: (ch.outlierCounts && ch.outlierCounts.mega) || 0,
    strong: (ch.outlierCounts && ch.outlierCounts.strong) || 0,
    good: (ch.outlierCounts && ch.outlierCounts.good) || 0,
  };
}

function saveChannelScout() {
  try {
    var arr = [];
    var keys = Object.keys(_channelMap);
    for (var i = 0; i < keys.length; i++) arr.push(_channelMap[keys[i]]);
    arr.sort(function(a, b) { return (b.avgOS || 0) - (a.avgOS || 0); });
    // Send all to background (which has chrome.storage access)
    for (var s = 0; s < arr.length; s++) {
      var sc = arr[s];
      saveToAllChannels({
        channelUrl: sc.channelUrl, channelId: '',
        name: sc.name, avatarUrl: sc.avatarUrl || '',
        subs: 0, revMonth: sc.rpm ? Math.round((sc.avgVPH || 0) * 24 * 30 * sc.rpm / 1000) : 0,
        avgOS: sc.avgOS || 0, topVPH: sc.topVPH || 0, topTier: sc.topTier || 'SLOW',
        niche: detectNicheLabel(sc.name + ' ' + (sc.query || '')),
        source: 'scout', savedAt: sc.lastSeen || Date.now(),
      });
    }
  } catch(e) {}
}

// ── Injection ────────────────────────────────────────────────────────────────

var _seen = {};

function isAshlyVCardCollectionActive() {
  return !!(window._ashlyv_scan_in_progress || _ashlyv_scan_in_progress || _ashlyv_scan_running);
}

function processCard(card) {
  var vidInfo = getVidId(card);
  var views = 0, hoursOld = null, isShort = false;

  if (vidInfo) {
    if (_seen[vidInfo.id]) return null;
    isShort = vidInfo.isShort;
    var ytEntry = getYtMap()[vidInfo.id];
    if (ytEntry && ytEntry.views) { views = ytEntry.views; hoursOld = ytEntry.hoursOld; isShort = ytEntry.isShort || isShort; }
  }
  if (!views) {
    var domData = getDomViews(card);
    if (domData) { views = domData.views; hoursOld = domData.hoursOld; }
  }
  if (hoursOld == null || !isFinite(hoursOld)) {
    var domAge = getDomAge(card);
    if (domAge) hoursOld = domAge.hoursOld;
  }
  if (!views || views < 1) return null;

  var key = (vidInfo ? vidInfo.id : '') || ('' + views + hoursOld);
  if (!key) return null;

  // BLOQUEAR: canales de musica. Los canales verificados no se descartan aquí:
  // muchos nichos faceless válidos vienen de canales verificados y el filtro final decide.
  try {
    // Buscar en todo el bloque del meta del video
    var chNameEl = card.querySelector('#channel-name a, ytd-channel-name a, .ytd-channel-name, ytd-video-meta-block a');
    var chName = chNameEl ? chNameEl.textContent.trim() : '';

    // M1: badge ytd-badge-supported-renderer (cualquier posicion en la tarjeta asociado al canal)
    var verifiedBadge =
      card.querySelector('ytd-video-owner-renderer ytd-badge-supported-renderer') ||
      card.querySelector('#channel-name ytd-badge-supported-renderer') ||
      card.querySelector('ytd-channel-name ytd-badge-supported-renderer') ||
      card.querySelector('#meta ytd-badge-supported-renderer') ||
      card.querySelector('#byline-container ytd-badge-supported-renderer') ||
      card.querySelector('ytd-video-meta-block ytd-badge-supported-renderer');

    // M2: aria-label con "verified"
    var ariaVerified = card.querySelector(
      '[aria-label*="verified"], [aria-label*="verificado"], [aria-label*="Verified"]'
    );

    // M3: simbolo de check en texto del canal
    var chBlock = card.querySelector('#channel-name, ytd-channel-name');
    var chText = chBlock ? chBlock.textContent : '';
    var hasCheckMark = chText.indexOf('\u2713') > -1 || chText.indexOf('\u2714') > -1 || chText.indexOf('\u2611') > -1;

    var isVerified = !!(verifiedBadge || ariaVerified || hasCheckMark);
    var isMusicLabel = /\bvevo\b|\bmusic\b|recordin|records|artista oficial|official artist|\blabel\b|\bsello\b|discogr|sony music|universal music|warner|emi\b/i.test(chName);

    if (isMusicLabel) return null;
  } catch(e) {}

  var title = '';
  var titleEl = null;
  try {
    titleEl = getVideoTitleNode(card);
    title = (titleEl || card.querySelector('h3 a') || {}).textContent || '';
  } catch(e) {}

  // Chequear badge en el punto EXACTO de inserción
  var insertParent = getBadgeInsertParent(card, titleEl);
  // FIX DOBLE PILL: en pagina de canal el video es un ytd-rich-item-renderer que CONTIENE un
  // ytd-rich-grid-media; ambos entran por SEL y cada uno insertaba su badge en un parent distinto.
  // Guard a nivel del CONTENEDOR del video (igual que ensureChannelCardBadge): maximo un badge por video.
  var videoBox = (card.closest && card.closest('ytd-rich-item-renderer, ytd-video-renderer, ytd-grid-video-renderer, ytd-compact-video-renderer')) || card;
  if ((videoBox.querySelector && videoBox.querySelector('.nsp-badge')) || (insertParent && insertParent.querySelector && insertParent.querySelector('.nsp-badge'))) {
    if (isAshlyVCardCollectionActive()) {
      videoBox.querySelectorAll('.nsp-badge').forEach(function(el) { el.remove(); });
    } else {
      return null;
    }
  }

  try {
    var liveText = (card.querySelector('ytd-thumbnail-overlay-time-status-renderer span, #text.ytd-thumbnail-overlay-time-status-renderer') || {}).textContent || '';
    if (/\blive\b|en vivo/i.test(liveText)) return null;
  } catch(e) {}

  try {
    var adBadge = card.querySelector('ytd-display-ad-renderer, ytd-ad-slot-renderer, ytd-promoted-sparkles-web-renderer, ytd-promoted-sparkles-text-search-renderer, [aria-label*="Sponsored"], [aria-label*="Patrocinado"]');
    var cardText = (card.textContent || '').replace(/\s+/g, ' ').trim();
    if (adBadge || /\bpatrocinado\b|\bsponsored\b|\bpromoted\b|\badvertisement\b|\banuncio\b/i.test(cardText)) return null;
  } catch(e) {}

  if (_seen[key]) return null;
  _seen[key] = true;

  // Duration from ytMap or DOM thumbnail time overlay
  var durationSecs = 0;
  var durationText = '';
  try {
    durationText = getCardDurationText(card, vidInfo, vidInfo && getYtMap()[vidInfo.id] ? getYtMap()[vidInfo.id].lengthText : '');
    durationSecs = parseDurationSecs(durationText);
  } catch(e) {}

  var sc = calcScore(views, hoursOld, isShort, title, durationSecs);
  if (!sc) return null;
  
  var subs = getDomSubs(card);
  var ytEntryForMeta = (vidInfo && getYtMap()[vidInfo.id]) || null;
  var rawPublishedText = (ytEntryForMeta && ytEntryForMeta.timeText) || (getDomViews(card) || {}).timeText || (getDomAge(card) || {}).timeText || '';
  sc.hoursOld = hoursOld;
  sc.publishedTimeText = rawPublishedText || '';
  sc.timeText = rawPublishedText || '';
  sc.ageText = rawPublishedText || '';
  sc.durationSecs = durationSecs;
  sc.lengthText = durationText || '';
  sc.title = title.trim();
  sc.vidId = vidInfo ? vidInfo.id : '';
  sc.views = views;
  sc.subs = subs;
  
  // Bonus por Outlier (vs subs, retained for OS scoring)
  if (subs > 0) sc.os += calculateOutlierBonus(views, subs);

  // Resolve channel identity BEFORE makeBadge so we can compute channel-outlier tier
  var ytChannel = vidInfo && getYtMap()[vidInfo.id] ? getYtMap()[vidInfo.id] : null;
  if (ytChannel) {
    if (!sc.channelUrl && ytChannel.channelUrl) sc.channelUrl = ytChannel.channelUrl;
    if (!sc.channelKey && ytChannel.channelKey) sc.channelKey = ytChannel.channelKey;
    if (!sc.channelId && ytChannel.channelId) sc.channelId = ytChannel.channelId;
    if (!sc.channelName && ytChannel.channelName) sc.channelName = ytChannel.channelName;
  }
  var chInfo = getChannelFromCard(card, vidInfo);
  if (chInfo) {
    if (!sc.channelUrl && chInfo.channelUrl) sc.channelUrl = chInfo.channelUrl;
    if (!sc.channelKey && chInfo.channelKey) sc.channelKey = chInfo.channelKey;
    if (!sc.channelId && chInfo.channelId) sc.channelId = chInfo.channelId;
    if (!sc.channelName && chInfo.name) sc.channelName = chInfo.name;
    updateChannelMap(chInfo, sc);
  }

  // Channel-outlier tier (views vs channel's own avg) — needs map already updated
  try {
    var chKey = sc.channelKey || sc.channelUrl;
    var chMapEntry = chKey ? _channelMap[chKey] : null;
    if (chMapEntry && chMapEntry.avgViews > 0) {
      sc._outlierTier = getChannelOutlierTier(sc.views, chMapEntry.avgViews);
    }
  } catch(e) {}

  var badge = makeBadge(views, sc);

  try {
    insertBadgeIntoCard(card, titleEl, badge);
  } catch(e) {}

  if (vidInfo) trackVideo(vidInfo.id, title.trim(), views, sc);

  return sc;
}

function collectSearchFallbackResults() {
  var out = [];
  var seenVideos = {};
  var links = Array.prototype.slice.call(document.querySelectorAll('a[href*="/watch?v="]'));

  links.forEach(function(link) {
    try {
      var href = link.getAttribute('href') || '';
      var m = href.match(/[?&]v=([^&\s#]+)/);
      if (!m) return;
      var videoId = m[1];
      if (!videoId || seenVideos[videoId]) return;

      var card = link.closest('yt-lockup-view-model, ytd-video-renderer, ytd-rich-item-renderer, ytd-compact-video-renderer, ytd-grid-video-renderer')
        || link.closest('#dismissible, #content, #details')
        || link.parentElement;
      if (!card) return;

      var titleNode = getVideoTitleNode(card) || link;
      var title = (titleNode.getAttribute('title') || titleNode.textContent || '').trim();
      if (!title || title.length < 3) return;

      var ytEntry = getYtMap()[videoId] || {};
      var domData = getDomViews(card) || parseViewsAgeFromText((link.getAttribute('aria-label') || '') + ' ' + (card.textContent || ''));
      var views = ytEntry.views || (domData && domData.views) || 0;
      var hoursOld = ytEntry.hoursOld != null ? ytEntry.hoursOld : (domData ? domData.hoursOld : null);
      if (hoursOld == null || !isFinite(hoursOld)) {
        var domAge = getDomAge(card) || parseAgeFromText((link.getAttribute('aria-label') || '') + ' ' + (card.textContent || ''));
        if (domAge) hoursOld = domAge.hoursOld;
      }
      if (!views || views < 1) return;

      var durationSecs = 0;
      var durationText = '';
      try {
        durationText = getCardDurationText(card, { id: videoId, isShort: false }, ytEntry.lengthText || (link.getAttribute('aria-label') || ''));
        durationSecs = parseDurationSecs(durationText);
      } catch(e) {}

      var sc = calcScore(views, hoursOld, false, title, durationSecs);
      if (!sc) return;

      var rawPublishedText = ytEntry.timeText || (domData && domData.timeText) || (domAge && domAge.timeText) || '';
      sc.hoursOld = hoursOld;
      sc.publishedTimeText = rawPublishedText || '';
      sc.timeText = rawPublishedText || '';
      sc.ageText = rawPublishedText || '';
      sc.durationSecs = durationSecs;
      sc.lengthText = durationText || '';
      sc.title = title;
      sc.vidId = videoId;
      sc.views = views;
      sc.subs = getDomSubs(card);
      if (sc.subs > 0) sc.os += calculateOutlierBonus(views, sc.subs);

      if (ytEntry.channelUrl) sc.channelUrl = ytEntry.channelUrl;
      if (ytEntry.channelKey) sc.channelKey = ytEntry.channelKey;
      if (ytEntry.channelId) sc.channelId = ytEntry.channelId;
      if (ytEntry.channelName) sc.channelName = ytEntry.channelName;

      var chInfo = getChannelFromCard(card, { id: videoId, isShort: false });
      if (chInfo) {
        if (!sc.channelUrl && chInfo.channelUrl) sc.channelUrl = chInfo.channelUrl;
        if (!sc.channelKey && chInfo.channelKey) sc.channelKey = chInfo.channelKey;
        if (!sc.channelId && chInfo.channelId) sc.channelId = chInfo.channelId;
        if (!sc.channelName && chInfo.name) sc.channelName = chInfo.name;
        updateChannelMap(chInfo, sc);
      }

      try {
        // Card-level dedupe (no card-wide .nsp-badge already)
        if (card.querySelector('.nsp-badge')) {
          // Already has one — skip insertion
        } else {
          var insertParent = getBadgeInsertParent(card, titleNode);
          if (insertParent && !insertParent.querySelector('.nsp-badge')) {
            var badge = makeBadge(views, sc);
            insertBadgeIntoCard(card, titleNode, badge);
          }
        }
      } catch(e) {}

      trackVideo(videoId, title, views, sc);
      seenVideos[videoId] = true;
      out.push({ card: card, sc: sc });
    } catch(e) {}
  });

  return out;
}

var SEL = 'ytd-video-renderer, ytd-rich-item-renderer, ytd-rich-grid-media, ytd-compact-video-renderer, ytd-grid-video-renderer, yt-lockup-view-model';

var _allScored = [];

function ensureChannelCardBadge(card) {
  if (!isChannelPage() || !card) return null;
  // FIX DOBLE PILL: mirar el CONTENEDOR del video (rich-item ancestro), no solo la card.
  // En pagina de canal el lockup entra aparte y su badge cae FUERA del alcance de card.querySelector
  // (esta arriba, en el rich-item), dejando pasar un 2do pill. Subir al contenedor lo evita.
  var nspBox = (card.closest && card.closest('ytd-rich-item-renderer, ytd-video-renderer, ytd-grid-video-renderer, ytd-compact-video-renderer')) || card;
  var hasExistingBadge = !!(card.querySelector('.nsp-badge') || (nspBox !== card && nspBox.querySelector && nspBox.querySelector('.nsp-badge')));
  if (hasExistingBadge && !isAshlyVCardCollectionActive()) return null;

  var titleNode = null;
  try { titleNode = getVideoTitleNode(card); } catch(e) {}

  var insertParent = null;
  try { insertParent = getBadgeInsertParent(card, titleNode, false); } catch(e) {}
  if (insertParent && insertParent.querySelector && insertParent.querySelector('.nsp-badge') && !isAshlyVCardCollectionActive()) return null;

  var sc = extractAnalysisVideoFromCard(card);
  if (!sc) return null;

  try {
    if (!(hasExistingBadge && isAshlyVCardCollectionActive())) {
      var badge = makeBadge(sc.views || 0, sc);
      insertBadgeIntoCard(card, titleNode, badge);
    }
  } catch(e) {}

  try {
    var chInfo = getChannelFromCard(card, sc.vidId ? { id: sc.vidId, isShort: false } : null);
    if (chInfo) updateChannelMap(chInfo, sc);
  } catch(e) {}

  try {
    if (sc.vidId) trackVideo(sc.vidId, sc.title || '', sc.views || 0, sc);
  } catch(e) {}

  return sc;
}

function run() {
  if (window._ashlyv_scan_in_progress) {
    try { injectTopScanButton(); } catch(e) {}
    return 0;
  }
  _session.query = new URLSearchParams(location.search).get('search_query') || '';
  var cards = document.querySelectorAll(SEL);
  var n = 0;
  for (var i = 0; i < cards.length; i++) {
    var sc = processCard(cards[i]);
    if (!sc && isChannelPage()) sc = ensureChannelCardBadge(cards[i]);
    if (sc) { n++; _allScored.push(sc); }
  }
  // Red de seguridad anti DOBLE PILL: como mucho UN badge por contenedor de video, pase lo que pase.
  try {
    document.querySelectorAll('ytd-rich-item-renderer, ytd-video-renderer, ytd-grid-video-renderer, ytd-compact-video-renderer').forEach(function(box) {
      var bs = box.querySelectorAll('.nsp-badge');
      for (var k = 1; k < bs.length; k++) { var hh = bs[k].closest('.nsp-channel-badge-host'); (hh || bs[k]).remove(); }
    });
  } catch(e) {}
  if (n > 0) {
    console.log('[NSP] injected=' + n + ' total=' + _session.analyzed);
    if (isSearchPage()) {
      try { injectFilterBar(); } catch(e){}
      try { injectCompetitionMeter(); } catch(e){}
    }
    try { setTimeout(function() { maybeEmitAshlyVLiveAlerts(false); }, 800); } catch(e) {}
  }
  try { if (isChannelPage()) injectChannelOverlay(); } catch(e) {}
  try { injectTopScanButton(); } catch(e) {}
  return n;
}

var _ashlyv_live_alert_last = 0;

function buildAshlyVLiveEntries(limit) {
  if (!ASHLYV_ENGINE || !ASHLYV_ENGINE.nicheScoring) return [];
  var uniqueLead = {};
  var scored = dedupeAshlyVScoredItems((_allScored || []).slice()).filter(function(sc) {
    return sc && sc.title && isRecentEnoughForAshlyV(sc);
  }).sort(function(a, b) {
    return (b.vph - a.vph) || (b.os - a.os);
  }).slice(0, limit || 48);

  return scored.map(function(sc) {
    var item = { sc: sc };
    var language = detectTextLanguage(getAshlyVLanguageText(item));
    var nicheText = [sc.title || '', sc.channelName || '', _session.query || ''].join(' ');
    var nicheId = ASHLYV_ENGINE.nicheScoring.inferNicheIdFromText(nicheText);
    var key = [language || 'unknown', nicheId || 'unknown'].join('|');
    if (!uniqueLead[key]) uniqueLead[key] = sc;
    return {
      title: sc.title || '',
      channelName: sc.channelName || '',
      channelUrl: sc.channelUrl || '',
      channelId: sc.channelId || '',
      vidId: sc.vidId || '',
      thumbUrl: sc.vidId ? ('https://i.ytimg.com/vi/' + sc.vidId + '/hqdefault.jpg') : '',
      language: language || 'unknown',
      niche: detectNicheLabel(nicheText),
      nicheId: nicheId,
      views: sc.views || 0,
      subs: sc.subs || 0,
      vph: sc.vph || 0,
      rpm: sc.rpm || 0,
      os: sc.os || 0,
      revMonth: sc.totalRev || sc.rev || 0,
      totalRev: sc.totalRev || 0,
      facelessScore: (sc._facelessAnalysis && sc._facelessAnalysis.facelessScore) || 50,
      facelessClassification: (sc._facelessAnalysis && sc._facelessAnalysis.classification) || 'borderline',
      hoursOld: sc.hoursOld,
      source: 'youtube-live',
      savedAt: Date.now(),
      _leadKey: key
    };
  });
}

function dismissAshlyVLiveToast(signature) {
  var toast = document.getElementById('ashlyv-live-toast');
  if (toast) toast.remove();
  if (signature) {
    sendRuntimeMessage({ type: 'ASHLYV_ALERT_DISMISS', signature: signature }).catch(function() {});
  }
}

// SECURITY: Sanitizes niche records before they are stored or sent to extension pages.
function sanitizeAshlyVNichoEntry(entry) {
  entry = entry && typeof entry === 'object' ? entry : {};
  function cleanText(value, max) { return String(value || '').replace(/[<>]/g, '').slice(0, max || 200); }
  function cleanNum(value, min, max) {
    var n = Number(value);
    if (!isFinite(n)) n = 0;
    if (typeof min === 'number' && n < min) n = min;
    if (typeof max === 'number' && n > max) n = max;
    return n;
  }
  return {
    title: cleanText(entry.title, 240),
    niche: cleanText(entry.niche || 'General', 160),
    nicheId: cleanText(entry.nicheId, 80),
    language: cleanText(entry.language || 'unknown', 40),
    channelUrl: /^https:\/\/(www\.)?youtube\.com\//i.test(String(entry.channelUrl || '')) ? String(entry.channelUrl).slice(0, 500) : '',
    channelId: cleanText(entry.channelId, 120),
    vidId: cleanText(entry.vidId, 40),
    thumbUrl: /^https:\/\/i\.ytimg\.com\//i.test(String(entry.thumbUrl || '')) ? String(entry.thumbUrl).slice(0, 500) : '',
    subs: cleanNum(entry.subs, 0, 1000000000),
    views: cleanNum(entry.views, 0, 100000000000),
    revMonth: cleanNum(entry.revMonth, 0, 1000000000),
    totalRev: cleanNum(entry.totalRev, 0, 1000000000),
    vph: cleanNum(entry.vph, 0, 1000000000),
    rpm: cleanNum(entry.rpm, 0, 1000),
    os: cleanNum(entry.os, 0, 1000000000),
    facelessScore: cleanNum(entry.facelessScore || 50, 0, 100),
    facelessClassification: cleanText(entry.facelessClassification || 'borderline', 40),
    scanSource: cleanText(entry.scanSource, 40),
    savedAt: cleanNum(entry.savedAt || Date.now(), 0, Date.now() + 60000),
    source: cleanText(entry.source || 'content-script', 80)
  };
}

var ASHLYV_DASHBOARD_PATH = 'ashlyv/ashlyv.html';

function getAshlyVDashboardBaseUrl() {
  try {
    if (typeof chrome !== 'undefined' && chrome.runtime && chrome.runtime.getURL) {
      return chrome.runtime.getURL(ASHLYV_DASHBOARD_PATH);
    }
  } catch(e) {}

  // El bridge ISOLATED expone el extension ID en este atributo del DOM (MAIN world
  // NO tiene chrome.runtime). Es la fuente confiable en la página de YouTube.
  try {
    var domExtId = document.documentElement.getAttribute('data-nsp-ext-id');
    if (domExtId && /^[a-z]{32}$/i.test(domExtId)) {
      return 'chrome-extension://' + domExtId + '/' + ASHLYV_DASHBOARD_PATH;
    }
  } catch(eDom) {}

  try {
    if (typeof window.__ASHLYV_DASHBOARD_URL === 'string' && /^chrome-extension:\/\/[a-z]{32}\/ashlyv\/ashlyv\.html$/i.test(window.__ASHLYV_DASHBOARD_URL)) {
      return window.__ASHLYV_DASHBOARD_URL;
    }
  } catch(e2) {}

  try {
    if (typeof window.__ASHLYV_EXTENSION_ID === 'string' && /^[a-z]{32}$/i.test(window.__ASHLYV_EXTENSION_ID)) {
      return 'chrome-extension://' + window.__ASHLYV_EXTENSION_ID + '/' + ASHLYV_DASHBOARD_PATH;
    }
  } catch(e3) {}

  return '';
}

function rememberAshlyVBridgeReady(data) {
  if (!data || data.type !== 'ASHLYV_BRIDGE_READY') return false;
  var dashboardUrl = String(data.dashboardUrl || '');
  var extensionId = String(data.extensionId || '');
  if (!/^chrome-extension:\/\/[a-z]{32}\/ashlyv\/ashlyv\.html$/i.test(dashboardUrl)) return false;
  if (!/^[a-z]{32}$/i.test(extensionId)) {
    var m = dashboardUrl.match(/^chrome-extension:\/\/([a-z]{32})\//i);
    extensionId = m ? m[1] : '';
  }
  if (!extensionId) return false;
  try {
    window.__ASHLYV_DASHBOARD_URL = dashboardUrl;
    window.__ASHLYV_EXTENSION_ID = extensionId;
  } catch(e) {}
  return true;
}

window.addEventListener('message', function(event) {
  if (!event || event.source !== window) return;
  if (event.origin && event.origin !== window.location.origin) return;
  rememberAshlyVBridgeReady(event.data);
});

// SECURITY: Saves/opens niches through extension messaging instead of leaking data via window.postMessage.
function buildAshlyVDashboardUrl(channelQuery, urlQuery) {
  try {
    var base = getAshlyVDashboardBaseUrl();
    if (!base) return '';
    var params = [];
    channelQuery = String(channelQuery || '').slice(0, 500);
    urlQuery = String(urlQuery || '').slice(0, 500);
    if (channelQuery) params.push('channel=' + encodeURIComponent(channelQuery));
    if (urlQuery && /^https:\/\/(www\.)?youtube\.com\//i.test(urlQuery)) params.push('url=' + encodeURIComponent(urlQuery));
    if (params.length) base += '?' + params.join('&');
    return base;
  } catch(e) {
    return '';
  }
}

function openAshlyVDashboardSecure(url) {
  url = String(url || getAshlyVDashboardBaseUrl()).slice(0, 1200);
  if (!url) return Promise.resolve({ ok: false, error: 'missing_url' });
  return sendRuntimeMessage({ type: 'ASHLYV_OPEN', url: url }).then(function(res) {
    if (res && res.ok) return res;
    try {
      var opened = window.open(url, '_blank', 'noopener');
      if (opened) return { ok: true, fallback: 'window_open' };
    } catch(e) {}
    return res || { ok: false, error: 'open_failed_youtube_tab_preserved' };
  });
}

function postAshlyVBridgeSaveOpen(entry, openPage, channelQuery, urlQuery) {
  try {
    var payload = {
      type: 'ASHLYV_OPEN_URL',
      ashlyvBridgeRequest: true,
      nichoData: entry,
      openPage: !!openPage,
      channelQuery: String(channelQuery || '').slice(0, 500),
      urlQuery: String(urlQuery || '').slice(0, 500)
    };
    if (typeof chrome !== 'undefined' && chrome.runtime && chrome.runtime.id) {
      payload.ashlyvInternal = chrome.runtime.id;
    }
    window.postMessage(payload, window.location.origin);
    return true;
  } catch(e) {}
  return false;
}

function saveAshlyVNichoSecure(nichoEntry, openPage, channelQuery, urlQuery) {
  var entry = sanitizeAshlyVNichoEntry(nichoEntry);
  // ── FAST PATH (MAIN world) ────────────────────────────────────────────────
  // El content script corre en MAIN world, donde chrome.runtime NO existe: por eso
  // sendRuntimeMessage SIEMPRE falla y window.open('chrome-extension://…') está
  // bloqueado por Chrome. El ÚNICO canal real es el bridge (ISOLATED). Vamos directo:
  // guarda Y abre el dashboard en un solo mensaje, al instante, sin arrastrar la
  // cadena de promesas que igual fallaría. Esto arregla "se demora / no abre".
  if (typeof chrome === 'undefined' || !chrome.runtime || !chrome.runtime.id) {
    var bridgedNow = postAshlyVBridgeSaveOpen(entry, !!openPage, channelQuery, urlQuery);
    return Promise.resolve({ ok: !!bridgedNow, bridged: bridgedNow, viaBridge: true });
  }
  var dashboardUrl = openPage ? buildAshlyVDashboardUrl(channelQuery, urlQuery) : '';
  function fallbackLocalSave() {
    return new Promise(function(resolve) {
      try {
        if (typeof chrome === 'undefined' || !chrome.storage || !chrome.storage.local) {
          resolve({ ok: false });
          return;
        }
        chrome.storage.local.get(['ashlyv_nichos', 'ashlyv_nichos_backup'], function(res) {
          var saved = Array.isArray(res.ashlyv_nichos) ? res.ashlyv_nichos.slice(0, 240) : [];
          saved.unshift(entry);
          var deduped = [];
          var seen = {};
          saved.forEach(function(item) {
            var key = String((item && (item.channelId || item.channelUrl || item.vidId || item.title || item.savedAt)) || '');
            if (!key || seen[key]) return;
            seen[key] = true;
            deduped.push(item);
          });
          deduped = deduped.slice(0, 240);
          chrome.storage.local.set({
            ashlyv_nichos: deduped,
            ashlyv_nichos_backup: deduped
          }, function() {
            resolve({ ok: !chrome.runtime.lastError, localFallback: true });
          });
        });
      } catch (e) {
        resolve({ ok: false, error: e && e.message ? e.message : 'local_save_failed' });
      }
    });
  }
  return sendRuntimeMessage({ type: 'ASHLYV_SAVE_NICHO', data: entry }).then(function(saveRes) {
    if (!saveRes || saveRes.ok !== true) {
      postAshlyVBridgeSaveOpen(entry, false, channelQuery, urlQuery);
      return fallbackLocalSave().then(function(localRes) {
        saveRes = saveRes || localRes;
        if (!openPage) return saveRes || { ok: false };
        return openAshlyVDashboardSecure(dashboardUrl).then(function(openRes) {
          var bridged = false;
          if (!openRes || openRes.ok !== true) {
            bridged = postAshlyVBridgeSaveOpen(entry, true, channelQuery, urlQuery);
          }
          return { ok: !!((openRes && openRes.ok === true) || bridged || (localRes && localRes.ok)), save: saveRes, open: openRes, bridged: bridged, local: localRes };
        });
      });
    }
    if (!openPage) return saveRes || { ok: false };
    return openAshlyVDashboardSecure(dashboardUrl).then(function(openRes) {
      var bridged = false;
      if (!openRes || openRes.ok !== true) {
        bridged = postAshlyVBridgeSaveOpen(entry, true, channelQuery, urlQuery);
      }
      return { ok: !!((openRes && openRes.ok === true) || bridged), save: saveRes, open: openRes, bridged: bridged };
    });
  }).catch(function(err) {
    var bridged = postAshlyVBridgeSaveOpen(entry, !!openPage, channelQuery, urlQuery);
    return fallbackLocalSave().then(function(localRes) {
      if (!openPage) {
        return { ok: !!(bridged || (localRes && localRes.ok)), bridged: bridged, local: localRes, error: err && err.message ? err.message : 'save_open_failed' };
      }
      return openAshlyVDashboardSecure(dashboardUrl || buildAshlyVDashboardUrl(channelQuery, urlQuery)).then(function(openRes) {
        return {
          ok: !!(bridged || (localRes && localRes.ok) || (openRes && openRes.ok)),
          bridged: bridged,
          local: localRes,
          open: openRes,
          error: err && err.message ? err.message : 'save_open_failed'
        };
      });
    });
  });
}

function saveAshlyVAlertLead(leadEntry) {
  if (!leadEntry) return;
  try {
    saveAshlyVNichoSecure({
      title: leadEntry.title || '',
      niche: leadEntry.niche || 'General',
      nicheId: leadEntry.nicheId || '',
      language: leadEntry.language || 'unknown',
      channelUrl: leadEntry.channelUrl || '',
      channelId: leadEntry.channelId || '',
      vidId: leadEntry.vidId || '',
      thumbUrl: leadEntry.thumbUrl || '',
      subs: leadEntry.subs || 0,
      views: leadEntry.views || 0,
      revMonth: leadEntry.revMonth || 0,
      totalRev: leadEntry.totalRev || 0,
      vph: leadEntry.vph || 0,
      rpm: leadEntry.rpm || 0,
      os: leadEntry.os || 0,
      facelessScore: leadEntry.facelessScore || 50,
      facelessClassification: leadEntry.facelessClassification || 'borderline',
      savedAt: Date.now(),
      source: 'live-alert'
    }, false, leadEntry.title || '', leadEntry.channelUrl || '');
  } catch(e) {}
}

function showAshlyVLiveToast(alert, opportunity, leadEntry) {
  var existing = document.getElementById('ashlyv-live-toast');
  if (existing) existing.remove();

  var signature = ASHLYV_ENGINE && ASHLYV_ENGINE.alertEngine && ASHLYV_ENGINE.alertEngine.signature
    ? ASHLYV_ENGINE.alertEngine.signature(alert)
    : '';

  var toast = document.createElement('div');
  toast.id = 'ashlyv-live-toast';
  toast.style.cssText = 'position:fixed;right:18px;bottom:18px;z-index:10004;width:360px;max-width:calc(100vw - 24px);'
    + 'border:1px solid rgba(255,255,255,.16);border-radius:24px;padding:16px;background:linear-gradient(180deg,rgba(0,0,0,.96),rgba(12,12,12,.92));'
    + 'box-shadow:0 24px 70px rgba(0,0,0,.72),0 0 26px rgba(255,255,255,.08),inset 0 1px 0 rgba(255,255,255,.04);'
    + 'backdrop-filter:blur(22px) saturate(150%);font-family:' + NSP_FONT_TEXT + ';color:#fff;';

  var opp = opportunity || {};
  var score = (alert && alert.opportunityScore) || opp.opportunityScore || 0;
  var verdict = opp.verdict || (score >= 8.6 ? 'ENTER NOW' : score >= 7.2 ? 'TEST' : 'WATCH');
  var badges = (opp.badges || []).slice(0, 3);
  var revLow = opp.estimatedMonthlyRevenueLow || 0;
  var revHigh = opp.estimatedMonthlyRevenueHigh || 0;
  var hasRev = revLow > 0 && revHigh > 0;

  var kickerText = verdict === 'ENTER NOW' ? 'HIGH PRIORITY OPPORTUNITY' : verdict === 'TEST' ? 'Niche Opportunity Detected' : 'ASHLYV Intelligence Update';
  var kicker = document.createElement('div');
  kicker.style.cssText = 'font-size:9px;font-family:' + NSP_FONT_MONO + ';letter-spacing:.18em;text-transform:uppercase;color:' + (verdict === 'ENTER NOW' ? 'rgba(255,140,60,.9)' : 'rgba(255,255,255,.54)') + ';';
  kicker.textContent = kickerText;
  toast.appendChild(kicker);

  var titleRow = document.createElement('div');
  titleRow.style.cssText = 'display:flex;align-items:center;gap:10px;margin-top:8px;';
  var title = document.createElement('div');
  title.style.cssText = 'font-size:20px;font-weight:900;line-height:1.15;font-family:' + NSP_FONT_DISPLAY + ';flex:1;';
  title.textContent = (alert && alert.title) || opp.recommendedNiche || 'Opportunity';
  titleRow.appendChild(title);
  var verdictPill = document.createElement('div');
  verdictPill.style.cssText = 'flex-shrink:0;padding:4px 10px;border-radius:999px;background:#fff;color:#000;font-family:' + NSP_FONT_DISPLAY + ';font-size:9px;font-weight:900;letter-spacing:.12em;text-transform:uppercase;';
  verdictPill.textContent = verdict;
  titleRow.appendChild(verdictPill);
  toast.appendChild(titleRow);

  if (hasRev) {
    var revLine = document.createElement('div');
    revLine.style.cssText = 'margin-top:8px;display:flex;align-items:baseline;gap:8px;';
    var revVal = document.createElement('span');
    revVal.style.cssText = 'font-family:' + NSP_FONT_DISPLAY + ';font-size:15px;font-weight:900;color:rgba(255,255,255,.92);';
    revVal.textContent = '$' + revLow + ' – $' + revHigh + '/mo';
    var revSub = document.createElement('span');
    revSub.style.cssText = 'font-size:10px;color:rgba(255,255,255,.44);font-family:' + NSP_FONT_MONO + ';letter-spacing:.1em;';
    revSub.textContent = 'est. revenue';
    revLine.appendChild(revVal);
    revLine.appendChild(revSub);
    toast.appendChild(revLine);
  }

  var meta = document.createElement('div');
  meta.style.cssText = 'margin-top:8px;font-size:11px;color:rgba(255,255,255,.58);line-height:1.7;';
  meta.textContent = [
    (NSP_LANGUAGE_META[(alert && alert.languageCode) || opp.languageCode || 'auto'] || { label: 'Auto / Global' }).label,
    'RPM ' + moneyLabel((alert && alert.rpm) || opp.estimatedRpm || 0),
    'Comp. ' + (opp.competitionLabel || 'Medium'),
    'Score ' + (score + '/10')
  ].join(' · ');
  toast.appendChild(meta);

  if (badges.length) {
    var badgeRow = document.createElement('div');
    badgeRow.style.cssText = 'display:flex;gap:6px;flex-wrap:wrap;margin-top:10px;';
    badges.forEach(function(badge) {
      var chip = document.createElement('div');
      var isHot = badge === 'FIRE' || badge === 'PREMIUM RPM';
      chip.style.cssText = 'display:inline-flex;align-items:center;height:24px;padding:0 9px;border-radius:999px;'
        + 'border:1px solid ' + (isHot ? 'rgba(255,120,40,.5)' : 'rgba(255,255,255,.15)') + ';'
        + 'background:' + (isHot ? 'rgba(255,100,30,.14)' : 'rgba(255,255,255,.04)') + ';'
        + 'color:' + (isHot ? '#ff8040' : 'rgba(255,255,255,.7)') + ';'
        + 'font-family:' + NSP_FONT_DISPLAY + ';font-size:8px;font-weight:900;letter-spacing:.12em;text-transform:uppercase;';
      chip.textContent = badge;
      badgeRow.appendChild(chip);
    });
    toast.appendChild(badgeRow);
  }

  var actions = document.createElement('div');
  actions.style.cssText = 'display:flex;gap:8px;flex-wrap:wrap;margin-top:14px;';

  function toastBtn(label, primary) {
    var btn = document.createElement('button');
    btn.textContent = label;
    btn.style.cssText = 'min-width:104px;height:38px;padding:0 12px;border-radius:14px;cursor:pointer;'
      + 'border:1px solid ' + (primary ? '#fff' : 'rgba(255,255,255,.14)') + ';'
      + 'background:' + (primary ? '#fff' : 'linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.02))') + ';'
      + 'color:' + (primary ? '#000' : '#fff') + ';font-family:' + NSP_FONT_DISPLAY + ';font-size:10px;font-weight:900;letter-spacing:.14em;text-transform:uppercase;';
    return btn;
  }

  var analyzeBtn = toastBtn('Analyze', true);
  analyzeBtn.onclick = function() {
    if (leadEntry && leadEntry.vidId) {
      var cards = document.querySelectorAll(SEL);
      for (var i = 0; i < cards.length; i++) {
        var info = getVidId(cards[i]);
        if (info && info.id === leadEntry.vidId) {
          cards[i].scrollIntoView({ behavior: 'smooth', block: 'center' });
          break;
        }
      }
    }
    dismissAshlyVLiveToast('');
    setTimeout(function() { showScanReport(); }, 200);
  };
  actions.appendChild(analyzeBtn);

  if (opp.nicheId) {
    var scanNicheBtn = toastBtn('Scan Niche', false);
    scanNicheBtn.onclick = function() {
      dismissAshlyVLiveToast('');
      try {
        var query = ASHLYV_ENGINE && ASHLYV_ENGINE.languageEngine && ASHLYV_ENGINE.languageEngine.buildQueryForNiche
          ? ASHLYV_ENGINE.languageEngine.buildQueryForNiche(opp.languageCode || 'auto', opp.nicheId)
          : (opp.recommendedNiche || '');
        if (query) {
          markAshlyVPendingSearchScan(query, { nicheId: opp.nicheId, languageCode: opp.languageCode, source: 'toast' });
          // Use localized URL builder so gl/hl from current market are injected
          window.location.href = buildLocalizedYouTubeSearchUrl(query, opp.languageCode);
        }
      } catch(e) {}
    };
    actions.appendChild(scanNicheBtn);
  }

  var saveBtn = toastBtn('Save', false);
  saveBtn.onclick = function() {
    saveAshlyVAlertLead(leadEntry);
    saveBtn.textContent = 'Saved';
  };
  actions.appendChild(saveBtn);

  var dashBtn = toastBtn('Dashboard', false);
  dashBtn.onclick = function() {
    sendRuntimeMessage({ type: 'ASHLYV_OPEN' }).catch(function() {});
    dismissAshlyVLiveToast('');
  };
  actions.appendChild(dashBtn);

  var dismissBtn = toastBtn('×', false);
  dismissBtn.style.minWidth = '38px';
  dismissBtn.style.width = '38px';
  dismissBtn.style.padding = '0';
  dismissBtn.onclick = function() { dismissAshlyVLiveToast(signature); };
  actions.appendChild(dismissBtn);

  toast.appendChild(actions);
  document.body.appendChild(toast);

  setTimeout(function() {
    if (document.getElementById('ashlyv-live-toast') === toast) toast.remove();
  }, 18000);
}

function maybeEmitAshlyVLiveAlerts(force) {
  if (!ASHLYV_ENGINE || !ASHLYV_ENGINE.nicheScoring) return;
  if (!force && (Date.now() - _ashlyv_live_alert_last) < 45000) return;
  _ashlyv_live_alert_last = Date.now();

  var liveEntries = buildAshlyVLiveEntries(42);
  if (!liveEntries.length) return;

  var selectedLanguage = getEffectiveLanguagePreference();
  var filterSet = ['fully_faceless'];
  var opportunities = ASHLYV_ENGINE.nicheScoring.buildLanguageMatrix(
    liveEntries,
    selectedLanguage && selectedLanguage !== 'auto' ? selectedLanguage : 'auto',
    filterSet,
    []
  );
  if (!opportunities || !opportunities.length) return;

  var top = opportunities[0];
  if (!top || top.opportunityScore < 7.6) return;

  var leadEntry = null;
  for (var i = 0; i < liveEntries.length; i++) {
    if (liveEntries[i].language === top.languageCode && liveEntries[i].nicheId === top.nicheId) {
      leadEntry = liveEntries[i];
      break;
    }
  }

  sendRuntimeMessage({ type: 'ASHLYV_OPPORTUNITY_HISTORY_PUSH', entries: opportunities.slice(0, 6) }).catch(function() {});
  var alert = ASHLYV_ENGINE.nicheScoring.buildAlertCandidateFromOpportunity(top, 'youtube-live');
  sendRuntimeMessage({ type: 'ASHLYV_ALERT_PUSH', alert: alert }).then(function(res) {
    if (res && res.ok && res.show) showAshlyVLiveToast(res.alert || alert, top, leadEntry);
  }).catch(function() {});
}

// ── Master SCAN Button & Report ─────────────────────────────────────────────



function normalizeYouTubeSearchLanguageCode(code) {
  code = String(code || '').toLowerCase().trim();
  if (!code || code === 'unknown') return '';
  if (code === 'jp') return 'ja';
  if (code === 'zh') return 'zh-cn';
  return code;
}

function getDefaultYouTubeSearchLocale() {
  var prefs = NspScanPrefs.get();
  var meta = NSP_MARKET_META[prefs.market];
  if (meta && meta.gl && meta.hl) return { hl: meta.hl, gl: meta.gl };
  var marketLanguage = getAshlyVLanguageForMarket(prefs.market);
  if (marketLanguage && NSP_YT_LOCALE_MAP[marketLanguage]) return NSP_YT_LOCALE_MAP[marketLanguage];
  return { hl: 'en', gl: 'US' };
}

function resolveYouTubeSearchLanguage(text, preferredCode) {
  var preferred = normalizeYouTubeSearchLanguageCode(preferredCode);
  if (preferred && preferred !== 'auto') return preferred;

  var facelessPayload = getActiveFacelessSearchPayload();
  if (facelessPayload && facelessPayload.code && facelessPayload.code !== 'auto') {
    return normalizeYouTubeSearchLanguageCode(facelessPayload.code);
  }

  var detected = normalizeYouTubeSearchLanguageCode(detectTextLanguage(text || ''));
  if (detected) return detected;

  var effective = normalizeYouTubeSearchLanguageCode(getEffectiveLanguagePreference());
  if (effective && effective !== 'auto') return effective;

  var prefsLanguage = normalizeYouTubeSearchLanguageCode(NspScanPrefs.get().language);
  if (prefsLanguage && prefsLanguage !== 'auto') return prefsLanguage;

  return '';
}

function getForcedTranslationTargetLanguage(text) {
  var preferred = resolveYouTubeSearchLanguage(text || '');
  if (!preferred || preferred === 'auto') return '';
  var detected = normalizeYouTubeSearchLanguageCode(detectTextLanguage(text || ''));
  if (detected && detected === preferred) return '';
  return preferred;
}

function buildLocalizedYouTubeSearchUrl(query, preferredCode) {
  var params = new URLSearchParams();
  var cleanQuery = String(query || '').replace(/\s+/g, ' ').trim();
  if (!cleanQuery) return 'https://www.youtube.com/';

  params.set('search_query', cleanQuery);

  var lang = resolveYouTubeSearchLanguage(cleanQuery, preferredCode);
  var prefs = NspScanPrefs.get();
  var marketMeta = NSP_MARKET_META[prefs.market];
  var locale;
  // Market overrides language when user explicitly picked a market
  if (marketMeta && marketMeta.gl && marketMeta.hl) {
    locale = { hl: marketMeta.hl, gl: marketMeta.gl };
  } else {
    locale = (lang && NSP_YT_LOCALE_MAP[lang]) || getDefaultYouTubeSearchLocale();
  }
  if (locale.hl) {
    params.set('hl', locale.hl);
    params.set('persist_hl', '1');
  }
  if (locale.gl) {
    params.set('gl', locale.gl);
    params.set('persist_gl', '1');
  }

  return 'https://www.youtube.com/results?' + params.toString();
}

function openLocalizedYouTubeSearch(query, preferredCode, meta) {
  var url = buildLocalizedYouTubeSearchUrl(query, preferredCode);
  markAshlyVPendingSearchScan(query, Object.assign({ source: 'open-localized-search', languageCode: preferredCode }, meta || {}));
  try { window.open(url, '_blank', 'noopener'); }
  catch(e) { window.open(url, '_blank'); }
}

function navigateToLocalizedYouTubeSearch(query, preferredCode, meta) {
  markAshlyVPendingSearchScan(query, Object.assign({ source: 'navigate-localized-search', languageCode: preferredCode }, meta || {}));
  window.location.href = buildLocalizedYouTubeSearchUrl(query, preferredCode);
}

function translateTitle(text, callback, forcedTargetLang) {
  var forced = normalizeYouTubeSearchLanguageCode(forcedTargetLang);
  if (forced && forced !== 'auto') {
    translateTo(text, forced, callback);
    return;
  }
  var detected = /[áéíóúñüÁÉÍÓÚÑÜ¿¡]/.test(text) || 
    /\b(el|la|los|las|que|para|con|una|del|por|como|pero|cómo|qué|fue|era|son)\b/i.test(text);
  var target = detected ? 'en' : 'es';
  translateTo(text, target, callback);
}

function translateTo(text, targetLang, callback) {
  text = String(text || '').slice(0, 1000);
  targetLang = String(targetLang || 'en').replace(/[^a-z-]/gi, '').slice(0, 12) || 'en';
  var url = 'https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=' + encodeURIComponent(targetLang) + '&dt=t&q=' + encodeURIComponent(text);
  ashlyv_safeFetch(url, { method: 'GET' }, 10000)
    .then(function(r) { return r.json(); })
    .then(function(data) {
      var t = '';
      if (data && data[0]) data[0].forEach(function(c) { if (c && c[0]) t += c[0]; });
      callback(t || text, targetLang);
    })
    .catch(function() { callback(text, targetLang); });
}

function saveNicheToWatchlist(key) {
  try {
    var wl = JSON.parse(localStorage.getItem('nsp_watchlist') || '[]');
    if (!wl.includes(key)) { wl.push(key); localStorage.setItem('nsp_watchlist', JSON.stringify(wl)); }
  } catch(e) {}
}

