function clearAshlyVPendingSearchScan() {
  try { sessionStorage.removeItem('ashlyv_pending_scan'); } catch(e) {}
  try { sessionStorage.removeItem(ASHLYV_PENDING_SEARCH_SCAN_KEY); } catch(e) {}
  try { localStorage.removeItem(ASHLYV_PENDING_SEARCH_SCAN_KEY); } catch(e) {}
}

function markAshlyVPendingSearchScan(query, meta) {
  var cleanQuery = normalizeFacelessQuery(query || '');
  if (!cleanQuery) {
    clearAshlyVPendingSearchScan();
    return;
  }
  var prefs = NspScanPrefs.get();
  var storedPayload = getStoredFacelessPayload && getStoredFacelessPayload();
  var languageCode = normalizeYouTubeSearchLanguageCode((meta && (meta.languageCode || meta.code)) || (storedPayload && storedPayload.code) || prefs.language || 'auto') || 'auto';
  var market = String((meta && meta.market) || (storedPayload && storedPayload.market) || prefs.market || 'global').toLowerCase();
  var depth = String((meta && meta.depth) || (storedPayload && storedPayload.depth) || prefs.depth || 'balanced').toLowerCase();
  var scanPrefs = normalizeLinkedScanPrefs(prefs, {
    language: languageCode && languageCode !== 'auto' ? languageCode : prefs.language,
    market: market,
    depth: depth
  });
  var payload = {
    query: cleanQuery,
    createdAt: Date.now(),
    source: (meta && meta.source) || 'localized-search',
    languageCode: scanPrefs.language,
    market: scanPrefs.market,
    depth: scanPrefs.depth,
    prefs: scanPrefs
  };
  try { sessionStorage.setItem('ashlyv_pending_scan', '1'); } catch(e) {}
  try { sessionStorage.setItem(ASHLYV_PENDING_SEARCH_SCAN_KEY, JSON.stringify(payload)); } catch(e) {}
  try { localStorage.setItem(ASHLYV_PENDING_SEARCH_SCAN_KEY, JSON.stringify(payload)); } catch(e) {}
}

function readAshlyVPendingSearchScan(storage) {
  try {
    var raw = storage.getItem(ASHLYV_PENDING_SEARCH_SCAN_KEY) || '';
    if (!raw) return null;
    var payload = JSON.parse(raw);
    if (!payload || !payload.query) return null;
    if (!payload.createdAt || (Date.now() - payload.createdAt) > ASHLYV_PENDING_SEARCH_SCAN_TTL_MS) return null;
    return payload;
  } catch(e) {
    return null;
  }
}

function consumeAshlyVPendingSearchScan() {
  if (!isSearchPage()) return false;
  var currentQuery = normalizeFacelessQuery(new URLSearchParams(location.search).get('search_query') || '');
  if (!currentQuery) return false;

  var storages = [sessionStorage, localStorage];
  for (var i = 0; i < storages.length; i++) {
    var payload = readAshlyVPendingSearchScan(storages[i]);
    if (!payload) continue;
    if (payload.query !== currentQuery) continue;
    if (payload.prefs || payload.languageCode || payload.market || payload.depth) {
      try {
        var restoredPrefs = normalizeLinkedScanPrefs(NspScanPrefs.get(), Object.assign({}, payload.prefs || {}, {
          language: payload.languageCode || (payload.prefs && payload.prefs.language) || NspScanPrefs.get().language,
          market: payload.market || (payload.prefs && payload.prefs.market) || NspScanPrefs.get().market,
          depth: payload.depth || (payload.prefs && payload.prefs.depth) || NspScanPrefs.get().depth
        }));
        NspScanPrefs.set(restoredPrefs);
        sessionStorage.setItem('nsp_faceless_payload', JSON.stringify({
          code: restoredPrefs.language || 'auto',
          language: restoredPrefs.language || 'auto',
          market: restoredPrefs.market || 'global',
          depth: restoredPrefs.depth || 'balanced',
          prefs: restoredPrefs,
          query: payload.query || currentQuery,
          source: payload.source || 'pending-search'
        }));
      } catch(e) {}
    }
    clearAshlyVPendingSearchScan();
    return true;
  }

  try {
    if (sessionStorage.getItem('ashlyv_pending_scan') === '1') {
      sessionStorage.removeItem('ashlyv_pending_scan');
      return true;
    }
  } catch(e) {}
  return false;
}

