          var titleKey = getAshlyVTitleClusterKey(item);
          var normalizedTitle = item && item.normalizedTitleBase || getAshlyVNormalizedTitleBase(sc.title || item.title || '');
          var depthBucket = getAshlyVDepthBucket(item);
          if (key && usedKeys[key]) return false;
          if (!options.relaxChannel && channelKey && channelCounts[channelKey] >= 1) return false;
          if (!options.relaxTitle && titleKey && titleClusters[titleKey] >= 1) return false;
          if (normalizedTitle && normalizedTitleCounts[normalizedTitle] >= 1) return false;
          if (!allowEarlyAtAll && depthBucket === 'early') return false;
          if (!options.allowExtraEarly && depthBucket === 'early' && depthCounts.early >= 1) return false;
          var idx = Number(item && item._cardIndex);
          var order = Number(item && item.globalDiscoveryOrder);
