          var tooClose = finalTop.some(function(prev) {
            var prevIdx = Number(prev && prev._cardIndex);
            var prevOrder = Number(prev && prev.globalDiscoveryOrder);
            var prevTop = Number(prev && (prev._cardTop != null ? prev._cardTop : prev.yPosition));
            if (isFinite(idx) && isFinite(prevIdx) && Math.abs(idx - prevIdx) < 6) return true;
            if (isFinite(order) && isFinite(prevOrder) && Math.abs(order - prevOrder) < 6) return true;
            if (isFinite(top) && isFinite(prevTop) && Math.abs(top - prevTop) < 1100) return true;
            return false;
          });
          if (tooClose) return false;
