          var key = item && item.dedupeKey || getAshlyVDedupeKeyFromSc(sc, item) || getItemKey(item) || getAshlyVResultKey(item);
          var channelKey = normalizeChannelNameKey(sc.channelName || item.channelName || sc.channelHandle || '') || String(sc.channelId || item.channelId || sc.channelKey || sc.channelUrl || '').toLowerCase();
          var titleKey = getAshlyVTitleClusterKey(item);
          var normalizedTitle = item && item.normalizedTitleBase || getAshlyVNormalizedTitleBase(sc.title || item.title || '');
          var depthBucket = getAshlyVDepthBucket(item);
