        takeFromPool(deepPool, deepTarget, 'deep-priority', { relaxChannel: false, relaxTitle: false, allowExtraEarly: false });
        takeFromPool(midPool, midTarget, 'mid-priority', { relaxChannel: false, relaxTitle: false, allowExtraEarly: false });
        if (allowEarlyAtAll && !finalTop.length && earlyPool.length) takeFromPool(earlyPool, 1, 'early-fallback', { relaxChannel: false, relaxTitle: false, allowExtraEarly: false });

