    _ctx.seenChannelUrls = _unique(mem.seenChannelUrls || mem.seenChannels);
    _ctx.seenChannelKeys = _unique(mem.seenChannelKeys);
    _ctx.seenTopicKeys = _unique(mem.seenTopicKeys || mem.seenTopics);
    _ctx.seenNicheLabels = _unique(mem.seenNicheLabels || mem.seenNiches);
