// ── ASHLYV Faceless Scoring System — Phase 3 ─────────────────────────────────
// Score-based system. NOT a blacklist. Hard rejects only for obvious cases.
var AshlyVRecentRuns = (function() {
  var KEY = 'ashlyv_recent_scan_runs_v1';
  var MAX_RUNS = 6;
  var _cache = null;

  function _load() {
    if (_cache) return _cache;
    try {
      var parsed = JSON.parse(sessionStorage.getItem(KEY) || '{"runs":[]}');
      if (!parsed || !Array.isArray(parsed.runs)) parsed = { runs: [] };
      _cache = parsed;
    } catch(e) {
      _cache = { runs: [] };
    }
    return _cache;
  }

  function _save() {
    try { sessionStorage.setItem(KEY, JSON.stringify(_cache || { runs: [] })); } catch(e) {}
  }

  function _collectSet(field) {
    var set = {};
    var data = _load();
    (data.runs || []).forEach(function(run) {
      (run[field] || []).forEach(function(value) {
        if (value) set[value] = true;
      });
    });
    return set;
  }

  function markTopResults(topResults) {
    if (!topResults || !topResults.length) return;
    var resultKeys = [];
    var channelKeys = [];
    var topicKeys = [];

    topResults.forEach(function(item) {
      var resultKey = getAshlyVResultKey(item);
      var channelKey = item && item.sc && (item.sc.channelKey || item.sc.channelUrl || item.sc.channelHandle || '');
      var topicKey = item && item.sc ? getAshlyVTopicKey(item.sc) : '';
      if (resultKey) resultKeys.push(resultKey);
      if (channelKey) channelKeys.push(('' + channelKey).trim().toLowerCase());
      if (topicKey) topicKeys.push(topicKey);
    });

    var data = _load();
    data.runs.unshift({
      ts: Date.now(),
      resultKeys: Array.from(new Set(resultKeys)),
      channelKeys: Array.from(new Set(channelKeys)),
      topicKeys: Array.from(new Set(topicKeys))
    });
    if (data.runs.length > MAX_RUNS) data.runs.length = MAX_RUNS;
    _cache = data;
    _save();
  }

  function filterResults(results) {
    var resultSet = _collectSet('resultKeys');
    var channelSet = _collectSet('channelKeys');
    var topicSet = _collectSet('topicKeys');
    return (results || []).filter(function(item) {
      var resultKey = getAshlyVResultKey(item);
      var channelKey = item && item.sc && (item.sc.channelKey || item.sc.channelUrl || item.sc.channelHandle || '');
      var topicKey = item && item.sc ? getAshlyVTopicKey(item.sc) : '';
      if (resultKey && resultSet[resultKey]) return false;
      if (channelKey && channelSet[('' + channelKey).trim().toLowerCase()]) return false;
      if (topicKey && topicSet[topicKey]) return false;
      return true;
    });
  }

  function isBlockedItem(item) {
    var resultSet = _collectSet('resultKeys');
    var channelSet = _collectSet('channelKeys');
    var topicSet = _collectSet('topicKeys');
    var resultKey = getAshlyVResultKey(item);
    var channelKey = item && item.sc && (item.sc.channelKey || item.sc.channelUrl || item.sc.channelHandle || '');
    var topicKey = item && item.sc ? getAshlyVTopicKey(item.sc) : '';
    if (resultKey && resultSet[resultKey]) return true;
    if (channelKey && channelSet[('' + channelKey).trim().toLowerCase()]) return true;
    if (topicKey && topicSet[topicKey]) return true;
    return false;
  }

  function reset() {
    _cache = { runs: [] };
    try { sessionStorage.removeItem(KEY); } catch(e) {}
  }

  function getStats() {
    var data = _load();
    return { recentRuns: (data.runs || []).length };
  }

  return {
    markTopResults: markTopResults,
    filterResults: filterResults,
    isBlockedItem: isBlockedItem,
    reset: reset,
    getStats: getStats
  };
})();

