// Make the panel draggable across the screen
function makeDraggable(overlay, handle) {
  if (!overlay || !handle) return;
  var isDown = false, startX, startY, initX, initY;
  handle.style.cursor = 'move';
  handle.onmousedown = function(e) {
    var target = e.target || {};
    if ((target.tagName && target.tagName.toLowerCase() === 'button') || (target.closest && target.closest('button'))) return;
    var rect = overlay.getBoundingClientRect ? overlay.getBoundingClientRect() : { left: overlay.offsetLeft || 0, top: overlay.offsetTop || 0 };
    isDown = true;
    startX = e.clientX; startY = e.clientY;
    initX = rect.left; initY = rect.top;
    overlay.style.right = 'auto';
    overlay.style.left = rect.left + 'px';
    overlay.style.top = rect.top + 'px';
    overlay.style.transform = 'none';
    document.onmousemove = function(me) {
      if (!isDown) return;
      overlay.style.left = (initX + me.clientX - startX) + 'px';
      overlay.style.top = (initY + me.clientY - startY) + 'px';
    };
    document.onmouseup = function() { isDown = false; document.onmousemove = null; document.onmouseup = null; };
    if (e.preventDefault) e.preventDefault();
  };
}

function calculateAshlyVTopResultsAvgRpm(topResults, fallbackAvgRpm) {
  var sum = 0;
  var count = 0;
  (topResults || []).forEach(function(item) {
    var sc = (item && item.sc) || item || {};
    var raw = Number(sc.rpm || item && (item.rpm || item._ashlyvRpmRaw) || 0);
    if ((!raw || !isFinite(raw)) && typeof detectRPM === 'function') {
      raw = Number(detectRPM([sc.title || item && item.title || '', item && item._nicheLabel || '', sc.channelName || ''].join(' ')) || 0);
    }
    if (raw && isFinite(raw) && raw > 0) {
      sum += raw;
      count++;
    }
  });
  if (!count) {
    var fallback = Number(String(fallbackAvgRpm || '').replace(/[$,\s]/g, ''));
    if (isFinite(fallback) && fallback > 0) return fallback.toFixed(2);
    return '0.00';
  }
  return (sum / count).toFixed(2);
}

