    + 'color:rgba(255,255,255,.65);font-size:13px;cursor:pointer;font-family:' + NSP_FONT_DISPLAY + ';'
    + 'box-shadow:inset 0 1px 0 rgba(255,255,255,.04);transition:all .16s;';
