document.addEventListener('yt-navigate-finish', function() {
  cancelAshlyVPreparedScan();
  setAshlyVScanInProgress(false);
  try { closeFacelessLanguagePanel(); } catch(e) {}
  _seen = {};
  _ytMap = null;
  _allScored = [];
  _channelMap = {};
  _filterTier = 'ALL';
  _filterMinVPH = 0;
  _channelOverlayDone = false;
  var fb = document.getElementById('nsp-filter-bar');
  var cb = document.getElementById('nsp-comp-bar');
  var co = document.getElementById('nsp-channel-overlay');
  var sp = document.getElementById('nsp-stats-panel');
  var fp = document.getElementById('nsp-faceless-panel');
  var fl = document.getElementById('nsp-faceless-btn');
  var sb = document.getElementById('nsp-batman-scan-btn');
  var gw = document.getElementById('nsp-globe-wrap');
  if (fb) fb.remove();
  if (cb) cb.remove();
  if (co) co.remove();
  if (sp) sp.remove();
  if (fp) fp.remove();
  // PERSISTENCIA VER STATS: si esta navegación te trajo DE VUELTA al canal del panel guardado, re-abrirlo
  try { setTimeout(nspMaybeReopenStatsPanel, 1600); } catch(eReo) {}
  if (fl) {
    fl.disabled = false;
    fl.dataset.nspBusy = '0';
    styleNSPMonoButton(fl, { compact: true, active: false });
    var flTxt = fl.querySelector('[data-faceless-label]');
    if (flTxt) flTxt.textContent = fl.dataset.nspBaseLabel || 'FACELESS';
  }
  if (sb && sb.parentNode) sb.parentNode.remove();
  if (gw) gw.remove();
  // Floating buttons cleanup
  ['nsp-transcript-btn-floating','nsp-transcript-panel','nsp-comments-btn-floating','nsp-comments-panel','nsp-similar-panel','nsp-titlelab-panel','nsp-thumblab-panel'].forEach(function(id) {
    var n = document.getElementById(id); if (n) n.remove();
  });
  setTimeout(run, 600);
  setTimeout(run, 1500);
  setTimeout(run, 3000);
  setTimeout(injectTranscriptButton, 800);
  setTimeout(injectTranscriptButton, 2200);
  setTimeout(injectCommentsButton, 900);
  setTimeout(injectCommentsButton, 2300);

  // Auto-scan si venimos de un SCAN de ASHLYV
  try {
    if (consumeAshlyVPendingSearchScan()) {
      setTimeout(function() { runAshlyVScanAuto(); }, 3800);
      return;
    }
    if (hasAshlyVPendingHomeScan() && isHomeFeedPage()) {
      setTimeout(function() { resumeAshlyVPendingHomeScan(); }, 3200);
    }
  } catch(e) {}
});

var _mt = null;
var _nspMainObserver = new MutationObserver(function() {
  var _now = Date.now();
  if (!window._ashlyv_mutation_reset || _now - window._ashlyv_mutation_reset > 1000) {
    window._ashlyv_mutation_count = 0;
    window._ashlyv_mutation_reset = _now;
  }
  window._ashlyv_mutation_count = (window._ashlyv_mutation_count || 0) + 1;
  if (window._ashlyv_mutation_count > 50) return;
  clearTimeout(_mt);
  _mt = setTimeout(function() {
    // Reinyectar botón si desapareció
    if (!document.getElementById('nsp-batman-scan-btn')) injectBatmanButton();
    if (!document.getElementById('nsp-globe-wrap')) injectGlobeButton();
    if (!document.getElementById('nsp-faceless-btn')) injectFacelessButton();
    if (getCurrentWatchVideoId() && !document.getElementById('nsp-transcript-btn-floating')) injectTranscriptButton();
    if (getCurrentWatchVideoId() && !document.getElementById('nsp-comments-btn-floating')) injectCommentsButton();
    if (window._ashlyv_scan_in_progress) return;
    run();
  }, 700);
});
_nspMainObserver.observe(document.documentElement, { childList: true, subtree: true });
window.addEventListener('beforeunload', function() {
  try { if (_nspMainObserver) _nspMainObserver.disconnect(); } catch(e) {}
  try { if (_mt) clearTimeout(_mt); } catch(e2) {}
  try { if (_ashlyv_integrity_timer) clearInterval(_ashlyv_integrity_timer); } catch(e3) {}
});

// ── Botón Batman ─────────────────────────────────────────────────────────────

function createBatmanScanIcon(width, height) {
  var svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', '0 0 100 60');
  svg.setAttribute('width', String(width || 22));
  svg.setAttribute('height', String(height || 14));
  svg.setAttribute('fill', '#fff');
  svg.style.cssText = 'flex-shrink:0;filter:drop-shadow(0 0 3px rgba(255,255,255,0.4));';
  var path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
  path.setAttribute('d', 'M50 15 C45 5 30 2 18 8 C10 12 4 20 2 28 C8 24 16 22 22 26 C18 30 16 36 18 42 C22 36 28 32 34 33 C36 38 40 44 44 48 C46 44 48 38 50 35 C52 38 54 44 56 48 C60 44 64 38 66 33 C72 32 78 36 82 42 C84 36 82 30 78 26 C84 22 92 24 98 28 C96 20 90 12 82 8 C70 2 55 5 50 15 Z');
  svg.appendChild(path);
  return svg;
}

function injectBatmanButton() {
  if (document.getElementById('nsp-batman-scan-btn')) return;
  var end = document.querySelector('ytd-masthead #end') || document.querySelector('#masthead #end');
  if (!end) return;

  var wrap = document.createElement('div');
  wrap.id = 'nsp-batman-scan-wrap';
  wrap.style.cssText = 'display:inline-flex;align-items:center;margin:0 8px;';

  var btn = document.createElement('button');
  btn.id = 'nsp-batman-scan-btn';
  btn.style.cssText = 'display:flex;align-items:center;gap:7px;height:36px;padding:0 14px;border-radius:18px;'
    + 'background:linear-gradient(135deg,#0a0a0a,#1a1a2e);border:1.5px solid rgba(255,255,255,0.15);'
    + 'color:#fff;font-size:11px;font-weight:900;cursor:pointer;font-family:Roboto,Arial,sans-serif;'
    + 'transition:all 0.2s;letter-spacing:0.1em;outline:none;'
    + 'box-shadow:0 2px 12px rgba(0,0,0,0.6);';

  var svg = createBatmanScanIcon(22, 14);

  var txt = document.createElement('span');
  txt.textContent = 'SCAN';

  btn.appendChild(svg);
  btn.appendChild(txt);

  btn.onmouseenter = function() { btn.style.background='linear-gradient(135deg,#1a1a2e,#2a2a4e)'; btn.style.transform='translateY(-1px)'; };
  btn.onmouseleave = function() { btn.style.background='linear-gradient(135deg,#0a0a0a,#1a1a2e)'; btn.style.transform='none'; };
  btn.onclick = showScanReport;

  wrap.appendChild(btn);
  end.prepend(wrap);
}

