function buildFacelessQueryPool() {
  var prefs = NspScanPrefs.get();
  var langs = getPreferredLanguages();
  var pool = [];
  FACELESS_QUERY_LIBRARY.forEach(function(entry) {
    if (entry && /^(?:personal-finance|business-case-study|crypto-investing|motivation-discipline|wealth-secrets|wellness-mindfulness|survival-tips)$/i.test(entry.key || '')) return;
    if (entry.markets && !entry.markets[prefs.market] && prefs.market !== 'global') return;
    if (prefs.language && prefs.language !== 'auto') {
      if (entry.terms[prefs.language]) pool.push(entry.terms[prefs.language]);
      else if (entry.terms.en) pool.push(entry.terms.en);
      return;
    }
    langs.forEach(function(lang) {
      if (entry.terms[lang]) pool.push(entry.terms[lang]);
    });
  });
  var seen = {};
  return pool.filter(function(q) {
    if (!q || seen[q]) return false;
    seen[q] = true;
    return true;
  });
}

