function nspShowFacelessVerdict() {
  if (location.pathname !== '/watch') return false;
  var old = document.getElementById('nsp-faceless-verdict');
  if (old) { old.remove(); return true; }
  var vid = '';
  try { vid = new URLSearchParams(location.search).get('v') || ''; } catch (eV) {}
  var titleEl = document.querySelector('h1.ytd-watch-metadata yt-formatted-string') || document.querySelector('#title h1 yt-formatted-string') || document.querySelector('h1.title');
  var chEl = document.querySelector('ytd-watch-metadata #channel-name a') || document.querySelector('#owner #channel-name a');
  var vTitle = String((titleEl && titleEl.textContent) || document.title.replace(/ - YouTube$/, '') || '').trim();
  var vChannel = String((chEl && chEl.textContent) || '').trim();
  if (!vTitle) return false;
  var item = { videoId: vid, sc: { title: vTitle, channelName: vChannel, vidId: vid, videoId: vid, thumbnail: vid ? 'https://i.ytimg.com/vi/' + vid + '/hqdefault.jpg' : '' } };
  var analysis = {};
  try { analysis = AshlyVFaceless.analyzeItem(item) || {}; } catch (eA) {}
  var profile = null;
  try { profile = getAshlyVGenerativeAiProfile(item); } catch (eP) {}
  var cls = String(analysis.classification || 'desconocido').toLowerCase();
  var fScore = Math.round(analysis.facelessScore || 0);

  var panel = document.createElement('div');
  panel.id = 'nsp-faceless-verdict';
  panel.style.cssText = 'position:fixed;top:70px;right:24px;z-index:2147483646;width:360px;max-width:calc(100vw - 32px);'
    + 'background:#000;border:1px solid rgba(255,255,255,.18);border-radius:16px;padding:16px;color:#fff;'
    + 'font-family:ui-monospace,monospace;box-shadow:0 20px 60px rgba(0,0,0,.75),0 0 24px rgba(255,255,255,.08);';
  function row(label, value, color) {
    var r = document.createElement('div');
    r.style.cssText = 'display:flex;justify-content:space-between;gap:10px;margin-top:7px;font-size:11px;';
    var l = document.createElement('span'); l.style.cssText = 'color:rgba(255,255,255,.55);'; l.textContent = label;
    var v = document.createElement('span'); v.style.cssText = 'color:' + (color || '#fff') + ';font-weight:800;text-align:right;'; v.textContent = value;
    r.appendChild(l); r.appendChild(v); panel.appendChild(r);
    return v;
  }
  var head = document.createElement('div');
  head.style.cssText = 'display:flex;justify-content:space-between;align-items:center;gap:10px;';
  var ht = document.createElement('div');
  ht.style.cssText = 'font-size:11px;font-weight:900;letter-spacing:.14em;color:#fff;text-shadow:0 0 8px rgba(255,255,255,.5);';
  ht.textContent = '🦇 VEREDICTO FACELESS';
  var hx = document.createElement('button');
  hx.textContent = '×';
  hx.style.cssText = 'background:none;border:none;color:rgba(255,255,255,.6);font-size:18px;cursor:pointer;line-height:1;';
  hx.onclick = function() { panel.remove(); };
  head.appendChild(ht); head.appendChild(hx);
  panel.appendChild(head);

  var big = document.createElement('div');
  big.style.cssText = 'margin-top:12px;padding:12px;border-radius:12px;text-align:center;font-size:14px;font-weight:900;letter-spacing:.06em;border:1px solid rgba(255,255,255,.14);';
  panel.appendChild(big);
  function setVerdict(state, extra) {
    if (state === 'si') {
      big.textContent = '✓ FACELESS REPLICABLE' + (extra || '');
      big.style.color = '#00FF88'; big.style.borderColor = 'rgba(0,255,136,.55)'; big.style.background = 'rgba(0,255,136,.08)'; big.style.textShadow = '0 0 10px rgba(0,255,136,.5)';
    } else if (state === 'no') {
      big.textContent = '✕ NO FACELESS' + (extra || '');
      big.style.color = '#FF6B6B'; big.style.borderColor = 'rgba(255,107,107,.55)'; big.style.background = 'rgba(255,107,107,.08)';
    } else {
      big.textContent = '⚠ DUDOSO' + (extra || '');
      big.style.color = '#FFD93D'; big.style.borderColor = 'rgba(255,217,61,.5)'; big.style.background = 'rgba(255,217,61,.07)';
    }
  }
  var isFacelessCls = (cls === 'faceless' || cls === 'faceless_ai' || cls === 'borderline');
  setVerdict(isFacelessCls && fScore >= 44 ? 'si' : (cls === 'hard_reject' || cls === 'not_faceless' ? 'no' : 'dudoso'), '');

  var tRow = document.createElement('div');
  tRow.style.cssText = 'margin-top:10px;font-size:10.5px;color:rgba(255,255,255,.75);line-height:1.4;';
  tRow.textContent = '"' + vTitle.slice(0, 90) + (vTitle.length > 90 ? '…' : '') + '" · ' + (vChannel || 'canal desconocido');
  panel.appendChild(tRow);

  row('Clasificación texto', cls.toUpperCase(), isFacelessCls ? '#00FF88' : '#FF6B6B');
  row('Score faceless', fScore + '/100', fScore >= 44 ? '#00FF88' : '#FFD93D');
  if (profile && profile.category) row('Categoría IA', String(profile.category) + ' (' + Math.round(profile.score || 0) + ')', '#fff');
  var visRow = row('Miniatura (face-api)', 'analizando…', '#FFD93D');
  if (profile && profile.hits && profile.hits.length) {
    var sig = document.createElement('div');
    sig.style.cssText = 'margin-top:10px;font-size:9.5px;color:rgba(255,255,255,.45);line-height:1.5;';
    sig.textContent = 'Señales: ' + profile.hits.slice(0, 4).join(' · ');
    panel.appendChild(sig);
  }
  document.body.appendChild(panel);
  try { window.addEventListener('yt-navigate-start', function() { try { panel.remove(); } catch (eRm) {} }, { once: true }); } catch (eNav) {}

  try {
    nspDetectFaceInThumbnail(item).then(function(f) {
      if (!f || f.unknown || !f.supported) { visRow.textContent = 'no evaluable'; visRow.style.color = 'rgba(255,255,255,.5)'; return; }
      if (f.hasFace && Number(f.faceArea || 0) >= 0.008) {
        visRow.textContent = '✕ CARA REAL detectada'; visRow.style.color = '#FF6B6B';
        setVerdict('no', ' (cara en miniatura)');
      } else {
        visRow.textContent = '✓ sin cara'; visRow.style.color = '#00FF88';
        if (isFacelessCls && fScore >= 44) setVerdict('si', ' (texto + visual)');
      }
    }).catch(function() { visRow.textContent = 'no evaluable'; visRow.style.color = 'rgba(255,255,255,.5)'; });
  } catch (eF) { visRow.textContent = 'no evaluable'; }
  return true;
}

function triggerFacelessButtonAction() {
  try { if (nspShowFacelessVerdict()) return; } catch (eVd) {}
  var hadPanel = !!document.getElementById('nsp-faceless-panel');
  var btn = document.getElementById('nsp-faceless-btn');
  if (btn && btn.disabled) {
    btn.disabled = false;
    btn.dataset.nspBusy = '0';
    styleNSPMonoButton(btn, { compact: true, active: false });
    var btnTxt = btn.querySelector('[data-faceless-label]');
    if (btnTxt) btnTxt.textContent = btn.dataset.nspBaseLabel || 'FACELESS';
  }
  try {
    var panel = showFacelessLanguagePanel();
    if (!hadPanel && !panel && !document.getElementById('nsp-faceless-panel')) {
      launchFacelessSearch(getLastFacelessLanguage() || 'auto');
    }
  } catch (err) {
    try { console.error('[NSP] faceless launcher failed', err); } catch(e) {}
    try { launchFacelessSearch(getLastFacelessLanguage() || 'auto'); } catch(e2) {}
  }
}

function showFacelessLanguagePanel() {
  var btn = document.getElementById('nsp-faceless-btn');
  if (!btn) return null;

  var existing = document.getElementById('nsp-faceless-panel');
  if (existing) {
    closeFacelessLanguagePanel();
    return null;
  }

  var rect = btn.getBoundingClientRect();
  var panelWidth = Math.min(460, Math.max(340, window.innerWidth - 24));
  var left = Math.min(Math.max(12, rect.left), Math.max(12, window.innerWidth - panelWidth - 12));

  var panel = document.createElement('div');
  panel.id = 'nsp-faceless-panel';
  panel.style.cssText = 'position:fixed;top:' + Math.round(rect.bottom + 12) + 'px;left:' + Math.round(left) + 'px;z-index:10002;'
    + 'width:' + panelWidth + 'px;max-width:calc(100vw - 24px);max-height:78vh;overflow:hidden;'
    + 'background:linear-gradient(180deg,rgba(0,0,0,.96),rgba(12,12,12,.9));border:1px solid rgba(255,255,255,.14);border-radius:26px;'
    + 'backdrop-filter:blur(22px) saturate(150%);box-shadow:0 26px 80px rgba(0,0,0,.7),0 0 0 1px rgba(255,255,255,.04),0 0 28px rgba(255,255,255,.08);'
    + 'font-family:' + NSP_FONT_TEXT + ';';
  panel.addEventListener('click', function(ev) { ev.stopPropagation(); });

  var header = document.createElement('div');
  header.style.cssText = 'padding:16px 16px 10px;display:flex;align-items:flex-start;justify-content:space-between;gap:12px;';

  var hLeft = document.createElement('div');
  hLeft.style.cssText = 'display:flex;flex-direction:column;gap:6px;min-width:0;';

  var title = document.createElement('div');
  title.style.cssText = 'font-size:12px;font-weight:900;color:#fff;letter-spacing:.18em;text-transform:uppercase;font-family:' + NSP_FONT_DISPLAY + ';';
  title.textContent = 'Faceless Language Matrix';
  hLeft.appendChild(title);

  var subtitle = document.createElement('div');
  subtitle.style.cssText = 'font-size:10px;color:rgba(255,255,255,.6);line-height:1.6;max-width:300px;';
  subtitle.textContent = 'Elige cualquier idioma, filtra el listado y disparo queries faceless locales. La busqueda abre y el scan corre solo.';
  hLeft.appendChild(subtitle);

  header.appendChild(hLeft);

  var closeBtn = document.createElement('button');
  closeBtn.textContent = 'X';
  closeBtn.style.cssText = 'width:34px;height:34px;border-radius:999px;border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.02);'
    + 'color:rgba(255,255,255,.66);font-size:12px;cursor:pointer;font-family:' + NSP_FONT_DISPLAY + ';'
    + 'box-shadow:inset 0 1px 0 rgba(255,255,255,.04);';
  closeBtn.onclick = closeFacelessLanguagePanel;
  header.appendChild(closeBtn);
  panel.appendChild(header);

  var body = document.createElement('div');
  body.style.cssText = 'padding:0 16px 16px;overflow-y:auto;max-height:calc(78vh - 64px);';
  var recentCodes = getRecentFacelessLanguages();
  var languageList = FACELESS_LANGUAGE_BANK.slice();
  var lastCode = getLastFacelessLanguage();

  var hero = document.createElement('div');
  hero.style.cssText = 'padding:14px 14px 12px;border-radius:20px;border:1px solid rgba(255,255,255,.1);'
    + 'background:linear-gradient(180deg,rgba(255,255,255,.06),rgba(255,255,255,.02));box-shadow:inset 0 1px 0 rgba(255,255,255,.05);';
  var heroTop = document.createElement('div');
  heroTop.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:10px;';
  var heroStat = document.createElement('div');
  heroStat.style.cssText = 'font-size:22px;font-weight:900;color:#fff;line-height:1;font-family:' + NSP_FONT_DISPLAY + ';text-shadow:0 0 12px rgba(255,255,255,.12);';
  heroStat.textContent = String(FACELESS_LANGUAGE_BANK.length - 1);
  heroTop.appendChild(heroStat);
  var heroLbl = document.createElement('div');
  heroLbl.style.cssText = 'font-size:9px;color:rgba(255,255,255,.42);letter-spacing:.16em;text-transform:uppercase;font-family:' + NSP_FONT_MONO + ';';
  heroLbl.textContent = 'Idiomas listos';
  heroTop.appendChild(heroLbl);
  hero.appendChild(heroTop);

  var heroTxt = document.createElement('div');
  heroTxt.style.cssText = 'font-size:10px;color:rgba(255,255,255,.68);line-height:1.65;margin-top:8px;';
  heroTxt.textContent = 'Auto Mix rota oportunidades globales. Si eliges idioma exacto, la busqueda queda bloqueada a ese idioma y solo entran videos recientes.';
  hero.appendChild(heroTxt);
  body.appendChild(hero);

  var quick = document.createElement('div');
  quick.style.cssText = 'display:flex;gap:8px;flex-wrap:wrap;margin-top:12px;';
  var autoBtn = document.createElement('button');
  styleNSPMonoButton(autoBtn, { compact: true, active: true });
  autoBtn.textContent = 'AUTO MIX';
  autoBtn.onclick = function() { launchFacelessSearch('auto'); };
  quick.appendChild(autoBtn);

  recentCodes.slice(0, 4).forEach(function(code) {
    var entry = FACELESS_LANGUAGE_MAP[code];
    if (!entry) return;
    var b = document.createElement('button');
    styleNSPMonoButton(b, { compact: true, active: false });
    b.textContent = ('RECENT ' + entry.label).toUpperCase();
    b.onclick = function() { launchFacelessSearch(code); };
    quick.appendChild(b);
  });
  body.appendChild(quick);

  var searchWrap = document.createElement('div');
  searchWrap.style.cssText = 'margin-top:12px;padding:12px;border-radius:18px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.03);'
    + 'box-shadow:inset 0 1px 0 rgba(255,255,255,.04);';
  var searchInput = document.createElement('input');
  searchInput.type = 'search';
  searchInput.placeholder = 'Buscar idioma, codigo o nombre nativo';
  searchInput.style.cssText = 'width:100%;height:42px;border-radius:14px;border:1px solid rgba(255,255,255,.12);background:rgba(0,0,0,.74);'
    + 'padding:0 14px;color:#fff;font-size:12px;outline:none;font-family:' + NSP_FONT_TEXT + ';';
  searchWrap.appendChild(searchInput);
  body.appendChild(searchWrap);

  var recentRow = document.createElement('div');
  recentRow.style.cssText = 'display:flex;gap:8px;flex-wrap:wrap;margin-top:10px;';
  recentCodes.forEach(function(code) {
    var recentEntry = FACELESS_LANGUAGE_MAP[code];
    if (!recentEntry) return;
    var chip = document.createElement('button');
    styleNSPMonoButton(chip, { compact: true, active: code === lastCode });
    chip.textContent = recentEntry.label.toUpperCase();
    chip.onclick = function() { launchFacelessSearch(code); };
    recentRow.appendChild(chip);
  });
  if (recentRow.childNodes.length) body.appendChild(recentRow);

  var grid = document.createElement('div');
  grid.style.cssText = 'display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:12px;';

  function renderGrid(query) {
    while (grid.firstChild) grid.removeChild(grid.firstChild);
    var normalizedQuery = String(query || '').toLowerCase().trim();
    languageList.filter(function(entry) {
      if (!entry || entry.code === 'auto') return false;
      if (!normalizedQuery) return true;
      var hay = [entry.label || '', entry.code || ''].join(' ').toLowerCase();
      return hay.indexOf(normalizedQuery) !== -1;
    }).forEach(function(entry) {
      var isLast = entry.code === lastCode;
      var tile = document.createElement('button');
      tile.type = 'button';
      tile.style.cssText = 'display:flex;flex-direction:column;align-items:flex-start;gap:7px;padding:12px;border-radius:16px;cursor:pointer;text-align:left;'
        + 'border:1px solid ' + (isLast ? 'rgba(255,255,255,.24)' : 'rgba(255,255,255,.1)') + ';'
        + 'background:' + (isLast ? 'linear-gradient(180deg,rgba(255,255,255,.09),rgba(0,0,0,.92))' : 'linear-gradient(180deg,rgba(255,255,255,.04),rgba(0,0,0,.94))') + ';'
        + 'box-shadow:' + (isLast ? '0 0 18px rgba(255,255,255,.08),inset 0 1px 0 rgba(255,255,255,.08)' : 'inset 0 1px 0 rgba(255,255,255,.04)') + ';'
        + 'transition:transform .16s,border-color .16s,box-shadow .16s,background .16s;';
      tile.onmouseenter = function() {
        tile.style.transform = 'translateY(-1px)';
        tile.style.borderColor = 'rgba(255,255,255,.24)';
        tile.style.boxShadow = '0 0 18px rgba(255,255,255,.08),inset 0 1px 0 rgba(255,255,255,.08)';
      };
      tile.onmouseleave = function() {
        tile.style.transform = 'none';
        tile.style.borderColor = isLast ? 'rgba(255,255,255,.24)' : 'rgba(255,255,255,.1)';
        tile.style.boxShadow = isLast ? '0 0 18px rgba(255,255,255,.08),inset 0 1px 0 rgba(255,255,255,.08)' : 'inset 0 1px 0 rgba(255,255,255,.04)';
      };
      tile.onclick = function() { launchFacelessSearch(entry.code); };

      var tileTop = document.createElement('div');
      tileTop.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%;';
      var tileLabel = document.createElement('div');
      tileLabel.style.cssText = 'font-size:11px;font-weight:900;color:#fff;line-height:1.25;font-family:' + NSP_FONT_DISPLAY + ';';
      tileLabel.textContent = entry.label;
      tileTop.appendChild(tileLabel);
      var mark = document.createElement('div');
      mark.style.cssText = 'font-size:8px;color:rgba(255,255,255,.56);letter-spacing:.12em;text-transform:uppercase;font-family:' + NSP_FONT_MONO + ';';
      mark.textContent = isLast ? 'Last' : String(entry.code || '').toUpperCase();
      tileTop.appendChild(mark);
      tile.appendChild(tileTop);

      var previewQueries = getFacelessPreviewQueries(entry.code, 2);
      var preview = document.createElement('div');
      preview.style.cssText = 'font-size:9px;color:rgba(255,255,255,.58);line-height:1.6;font-family:' + NSP_FONT_MONO + ';';
      preview.textContent = previewQueries.join(' | ');
      tile.appendChild(preview);

      grid.appendChild(tile);
    });
  }

  renderGrid('');
  searchInput.addEventListener('input', function() { renderGrid(searchInput.value || ''); });

  body.appendChild(grid);

  var foot = document.createElement('div');
  foot.style.cssText = 'font-size:9px;color:rgba(255,255,255,.42);line-height:1.65;margin-top:12px;padding-bottom:2px;';
  foot.textContent = '1 click = busqueda + auto scan + idioma bloqueado. La ventana faceless usa maximo 90 dias para que no entren videos muertos.';
  body.appendChild(foot);

  panel.appendChild(body);
  document.body.appendChild(panel);
  setNSPMonoButtonActive(btn, true);

  var onDocClick = function(ev) {
    if (!panel.contains(ev.target) && !btn.contains(ev.target)) closeFacelessLanguagePanel();
  };
  panel._nspDocClose = onDocClick;
  setTimeout(function() {
    try { document.addEventListener('click', onDocClick, true); } catch(e) {}
  }, 0);
  return panel;
}

function showFacelessScan() {
  triggerFacelessButtonAction();
}

var _nspGlobeIconSeq = 0;

function createGlobeIcon(size) {
  var svgNS = 'http://www.w3.org/2000/svg';
  var iconSize = size || 20;
  var clipId = 'nsp-globe-clip-' + (++_nspGlobeIconSeq);

  function svgEl(tag, attrs) {
    var node = document.createElementNS(svgNS, tag);
    var key;
    for (key in (attrs || {})) node.setAttribute(key, attrs[key]);
    return node;
  }

  var orb = document.createElement('span');
  orb.className = 'nsp-globe-orb';
  orb.style.width = String(iconSize) + 'px';
  orb.style.height = String(iconSize) + 'px';

  var glow = document.createElement('span');
  glow.className = 'nsp-globe-glow';
  orb.appendChild(glow);

  var shell = document.createElement('span');
  shell.className = 'nsp-globe-shell';
  orb.appendChild(shell);

  var ring = document.createElement('span');
  ring.className = 'nsp-globe-ring';
  orb.appendChild(ring);

  var svg = svgEl('svg', {
    viewBox: '0 0 100 100',
    class: 'nsp-globe-svg',
    'aria-hidden': 'true',
    focusable: 'false'
  });

  var defs = svgEl('defs');
  var clip = svgEl('clipPath', { id: clipId });
  clip.appendChild(svgEl('circle', { cx: '50', cy: '50', r: '45' }));
  defs.appendChild(clip);
  svg.appendChild(defs);

  var map = svgEl('g', { class: 'nsp-globe-map', 'clip-path': 'url(#' + clipId + ')' });

  var grid = svgEl('g', { class: 'nsp-globe-grid' });
  [
    { tag: 'ellipse', attrs: { cx: '50', cy: '50', rx: '35', ry: '45' } },
    { tag: 'ellipse', attrs: { cx: '50', cy: '50', rx: '20', ry: '45' } },
    { tag: 'ellipse', attrs: { cx: '50', cy: '50', rx: '8', ry: '45' } },
    { tag: 'ellipse', attrs: { cx: '50', cy: '50', rx: '45', ry: '32' } },
    { tag: 'ellipse', attrs: { cx: '50', cy: '50', rx: '45', ry: '18' } },
    { tag: 'ellipse', attrs: { cx: '50', cy: '50', rx: '45', ry: '7' } }
  ].forEach(function(item) {
    grid.appendChild(svgEl(item.tag, item.attrs));
  });
  map.appendChild(grid);

  var continents = svgEl('g', { class: 'nsp-globe-continents' });
  continents.appendChild(svgEl('path', {
    d: 'M29 18C24 21 20 27 19 34C18 41 20 46 24 51C26 54 26 58 24 62C22 67 24 73 28 79C31 84 36 84 38 79C39 75 38 69 40 64C42 59 44 56 43 51C42 47 39 43 36 39C33 35 34 29 37 25C38 22 35 18 29 18Z'
  }));
  continents.appendChild(svgEl('path', {
    d: 'M52 20C58 19 65 21 71 24C74 26 78 27 81 28C83 29 83 32 81 34C79 36 75 36 72 38C68 40 66 43 64 46C62 49 60 51 57 51C54 51 52 49 50 46C48 43 45 40 46 36C47 32 50 30 50 25C50 22 50 21 52 20Z'
  }));
  continents.appendChild(svgEl('path', {
    d: 'M57 46C61 47 64 51 65 56C66 62 64 68 61 73C58 77 54 79 52 75C50 71 51 66 49 61C47 56 48 50 51 48C53 46 55 45 57 46Z'
  }));
  continents.appendChild(svgEl('path', {
    d: 'M74 68C78 68 81 70 83 73C84 76 82 79 78 80C74 81 70 79 69 75C69 71 71 68 74 68Z'
  }));
  map.appendChild(continents);

  svg.appendChild(map);
  svg.appendChild(svgEl('circle', { cx: '50', cy: '50', r: '45', class: 'nsp-globe-outline' }));
  orb.appendChild(svg);

  var highlight = document.createElement('span');
  highlight.className = 'nsp-globe-highlight';
  orb.appendChild(highlight);

  return orb;
}

function createPrefsOptionButton(label, active) {
  var btn = document.createElement('button');
  btn.textContent = label;
  btn.style.cssText = 'padding:6px 9px;border-radius:9px;border:1px solid '
    + (active ? 'rgba(255,255,255,.24)' : 'rgba(255,255,255,.08)') + ';background:'
    + (active ? 'linear-gradient(135deg,rgba(255,255,255,.12),rgba(18,18,18,.96))' : 'rgba(255,255,255,.03)')
    + ';color:' + (active ? '#fff' : 'rgba(255,255,255,.72)') + ';font-size:9.5px;font-weight:800;cursor:pointer;'
    + 'font-family:' + NSP_FONT_DISPLAY + ';letter-spacing:.04em;white-space:nowrap;box-shadow:' + (active ? '0 0 18px rgba(255,255,255,.08)' : 'none') + ';';
  return btn;
}

function renderGlobeDropdown(panel, summaryEl) {
  var prefs = NspScanPrefs.get();
  while (panel.firstChild) panel.removeChild(panel.firstChild);
  panel.style.fontFamily = NSP_FONT_TEXT;
  var top = document.createElement('div');
  top.style.cssText = 'padding:12px 14px;background:linear-gradient(135deg,rgba(255,255,255,.05),rgba(255,255,255,.015));border-bottom:1px solid rgba(255,255,255,.05);';
  var topTitle = document.createElement('div');
  topTitle.style.cssText = 'font-size:11px;font-weight:900;color:#fff;letter-spacing:.16em;text-transform:uppercase;font-family:' + NSP_FONT_DISPLAY + ';';
  topTitle.textContent = 'Global Scan Control';
  var topSummary = document.createElement('div');
  topSummary.style.cssText = 'font-size:8.5px;color:rgba(255,255,255,.42);margin-top:4px;line-height:1.45;font-family:' + NSP_FONT_MONO + ';';
  top.appendChild(topTitle);
  top.appendChild(topSummary);
  panel.appendChild(top);

  var act = document.createElement('div');
  act.style.cssText = 'padding:10px 12px;border-bottom:1px solid rgba(255,255,255,.05);display:flex;flex-direction:column;gap:8px;';
  var scanNowBtn = document.createElement('button');
  scanNowBtn.textContent = '🦇 ESCANEAR AHORA CON ESTA CONFIG';
  scanNowBtn.style.cssText = 'width:100%;padding:11px 12px;border-radius:10px;border:1px solid rgba(0,255,136,.5);background:linear-gradient(135deg,rgba(0,255,136,.16),rgba(0,0,0,.9));color:#00FF88;font-size:11px;font-weight:900;letter-spacing:.08em;cursor:pointer;font-family:' + NSP_FONT_DISPLAY + ';box-shadow:0 0 18px rgba(0,255,136,.15);';
  scanNowBtn.onclick = function(e) {
    e.preventDefault();
    var pNow = NspScanPrefs.get();
    var mNow = NSP_MARKET_META[pNow.market] || {};
    try { panel.style.display = 'none'; } catch (ePd) {}
    if (mNow.gl && mNow.hl) { syncYouTubePrefCookieFromPrefs(); return; }
    if (typeof showScanReport === 'function') { showScanReport(); return; }
    var bBtn = document.getElementById('nsp-batman-scan-btn');
    if (bBtn) bBtn.click();
  };
  act.appendChild(scanNowBtn);
  var scanStat = document.createElement('div');
  scanStat.style.cssText = 'font-size:8.5px;color:rgba(255,255,255,.5);line-height:1.5;font-family:' + NSP_FONT_MONO + ';';
  (function fillScanStat() {
    var nRes = (window._ashlyv_last_top_results || []).length;
    var nFilt = (typeof NSP_LAST_FILTERED_COUNT === 'number') ? NSP_LAST_FILTERED_COUNT : 0;
    if (!nRes) { scanStat.textContent = 'Sin scans en esta sesión — elegí país/idioma/profundidad y dale ESCANEAR.'; return; }
    var ago = '';
    try { if (window._nspLastScanTs) { var mAgo = Math.max(0, Math.round((Date.now() - window._nspLastScanTs) / 60000)); ago = ' · hace ' + mAgo + ' min'; } } catch (eAg) {}
    scanStat.textContent = 'Último scan: ' + nRes + ' nichos en el panel · ' + nFilt + ' descartados por país/idioma' + ago;
  })();
  act.appendChild(scanStat);
  panel.appendChild(act);

  function section(title, subtitle, options, selected, key) {
    var box = document.createElement('div');
    box.style.cssText = 'padding:10px 12px;border-bottom:1px solid rgba(255,255,255,.05);';
    var head = document.createElement('div');
    head.style.cssText = 'display:flex;align-items:flex-start;justify-content:space-between;gap:8px;margin-bottom:8px;';
    var headLeft = document.createElement('div');
      var t = document.createElement('div');
      t.style.cssText = 'font-size:10px;font-weight:900;color:#fff;letter-spacing:.12em;text-transform:uppercase;font-family:' + NSP_FONT_DISPLAY + ';';
      t.textContent = title;
      var st = document.createElement('div');
      st.style.cssText = 'font-size:8.5px;color:rgba(255,255,255,.36);margin-top:3px;line-height:1.45;';
    st.textContent = subtitle;
    headLeft.appendChild(t);
    headLeft.appendChild(st);
    head.appendChild(headLeft);
    box.appendChild(head);

    var grid = document.createElement('div');
    grid.style.cssText = 'display:flex;flex-wrap:wrap;gap:6px;';
    options.forEach(function(opt) {
      var btn = createPrefsOptionButton(opt.label, opt.value === selected);
      btn.onclick = function(e) {
        e.preventDefault();
        NspScanPrefs.set((function() { var next = {}; next[key] = opt.value; return next; })()).then(function() {
          renderGlobeDropdown(panel, summaryEl);
          // If market changed, sync YouTube PREF cookie + offer reload
          if (key === 'market' || key === 'language') {
            syncYouTubePrefCookieFromPrefs();
            refreshGlobeBadgeIfReady();
          }
        });
      };
      grid.appendChild(btn);
    });
    box.appendChild(grid);
    panel.appendChild(box);
  }

  section('Elegir idioma', 'Filtro HARD: solo videos detectados en el idioma elegido aparecen en el scan.', [
    { label:'🌍 Auto', value:'auto' },
    { label:'English', value:'en' },
    { label:'Spanish', value:'es' },
    { label:'German', value:'de' },
    { label:'French', value:'fr' },
    { label:'Polish', value:'pl' },
    { label:'Japanese', value:'ja' },
    { label:'Dutch', value:'nl' },
    { label:'Swedish', value:'sv' },
    { label:'Norwegian', value:'no' },
    { label:'Danish', value:'da' },
    { label:'Italian', value:'it' }
  ], prefs.language, 'language');

  // Market options generated dynamically from NSP_MARKET_META (single source of truth)
  var marketOptions = Object.keys(NSP_MARKET_META).map(function(key) {
    var m = NSP_MARKET_META[key];
    return { label: (m.flag ? m.flag + ' ' : '') + m.label, value: key };
  });
  section('Modo de mercado', 'Filtro HARD por país: inyecta gl/hl en YouTube y descarta resultados off-market.', marketOptions, prefs.market, 'market');

  section('Profundidad', 'Define cuántos resultados y videos inspecciona el sistema antes de rankear.', [
    { label:'Fast', value:'fast' },
    { label:'Balanced', value:'balanced' },
    { label:'Deep', value:'deep' }
  ], prefs.depth, 'depth');

  var summaryText = [
    NSP_LANGUAGE_META[prefs.language].label,
    NSP_MARKET_META[prefs.market].label,
    NSP_DEPTH_META[prefs.depth].label
  ].join(' | ');
  topSummary.textContent = summaryText;
  if (summaryEl) {
    try {
      summaryEl.title = summaryText;
      summaryEl.setAttribute('aria-label', 'Global Scan Control | ' + summaryText);
      summaryEl.setAttribute('data-summary', summaryText);
    } catch(e) {}
  }
}

function injectGlobeButton() {
  if (document.getElementById('nsp-globe-wrap')) return;
  var end = document.querySelector('ytd-masthead #end') || document.querySelector('#masthead #end');
  if (!end) return;

  var wrap = document.createElement('div');
  wrap.id = 'nsp-globe-wrap';
  wrap.style.cssText = 'position:relative;display:inline-flex;align-items:center;margin:0 8px 0 6px;flex:0 0 auto;';

  var btn = document.createElement('button');
  btn.id = 'nsp-globe-btn';
  btn.className = 'nsp-globe-btn nsp-globe-compact';
  btn.style.cssText = 'display:inline-flex;align-items:center;justify-content:center;width:40px;height:40px;padding:0;border:none;background:transparent;'
    + 'color:#fff;cursor:pointer;outline:none;transition:transform .18s ease,filter .18s ease;position:relative;box-shadow:none;';
  btn.appendChild(createGlobeIcon(28));

  var panel = document.createElement('div');
  panel.id = 'nsp-globe-panel';
  panel.style.cssText = 'display:none;position:absolute;top:44px;right:-8px;width:336px;max-width:calc(100vw - 24px);'
    + 'background:linear-gradient(180deg,rgba(0,0,0,.96),rgba(12,12,12,.94));border:1px solid rgba(255,255,255,.12);'
    + 'border-radius:16px;overflow:hidden;box-shadow:0 20px 60px rgba(0,0,0,.78),0 0 30px rgba(255,255,255,.08);z-index:10020;';

  renderGlobeDropdown(panel, btn);
  wrap.appendChild(btn);
  wrap.appendChild(panel);

  // ── STATUS BADGE (floating below the globe button) ──
  var badge = document.createElement('div');
  badge.id = 'nsp-globe-badge';
  badge.style.cssText = 'position:absolute;top:46px;right:0;display:inline-flex;align-items:center;gap:5px;'
    + 'padding:4px 8px;border-radius:8px;background:rgba(0,0,0,.82);border:1px solid rgba(255,255,255,.12);'
    + 'color:rgba(255,255,255,.82);font-family:' + NSP_FONT_DISPLAY + ';font-size:8.5px;font-weight:700;'
    + 'letter-spacing:.06em;white-space:nowrap;pointer-events:none;backdrop-filter:blur(8px) saturate(140%);'
    + 'box-shadow:0 4px 14px rgba(0,0,0,.4),inset 0 1px 0 rgba(255,255,255,.05);z-index:10019;'
    + 'text-transform:uppercase;';
  wrap.appendChild(badge);

  // Expose refresher globally so filterResultsByUserScanPreferences can update count
  window.__nspRefreshGlobeBadge = function() {
    try {
      var prefs = NspScanPrefs.get();
      try {
        var rawPay = sessionStorage.getItem('nsp_faceless_payload');
        var payPrefs = rawPay ? (JSON.parse(rawPay) || {}).prefs : null;
        if (payPrefs && typeof payPrefs === 'object') prefs = payPrefs;
        var lastLang = localStorage.getItem('nsp_faceless_last_lang');
        if (lastLang && lastLang !== 'auto') prefs = Object.assign({}, prefs, { language: lastLang });
      } catch(ePref) {}
      var marketMeta = NSP_MARKET_META[prefs.market] || {};
      var langCode = prefs.language === 'auto'
        ? (marketMeta.lang || 'auto')
        : prefs.language;
      var depthLabel = (NSP_DEPTH_META[prefs.depth] || {}).label || prefs.depth;
      var marketFlag = marketMeta.flag || '🌍';
      var marketCode = marketMeta.gl || 'GL';
      var filtered = (typeof NSP_LAST_FILTERED_COUNT === 'number') ? NSP_LAST_FILTERED_COUNT : 0;
      badge.textContent = marketFlag + ' ' + marketCode + ' · ' + langCode + ' · ' + depthLabel + ' · ' + filtered + ' filt';
      // Color-code if filter is doing work
      if (filtered > 0) {
        badge.style.borderColor = 'rgba(255,217,61,.35)';
        badge.style.color = 'rgba(255,217,61,.95)';
      } else {
        badge.style.borderColor = 'rgba(255,255,255,.12)';
        badge.style.color = 'rgba(255,255,255,.82)';
      }
    } catch(e) {}
  };
  window.__nspRefreshGlobeBadge();

  btn.onmouseenter = function() { btn.style.transform = 'scale(1.06)'; btn.style.filter = 'brightness(1.08)'; };
  btn.onmouseleave = function() { btn.style.transform = 'none'; btn.style.filter = 'none'; };
  btn.onclick = function(e) {
    e.preventDefault();
    e.stopPropagation();
    panel.style.display = panel.style.display === 'block' ? 'none' : 'block';
    if (panel.style.display === 'block') renderGlobeDropdown(panel, btn);
  };

  document.addEventListener('click', function(ev) {
    if (!wrap.contains(ev.target)) panel.style.display = 'none';
  });

  var scanWrap = document.getElementById('nsp-batman-scan-wrap');
  if (scanWrap && scanWrap.parentNode === end) {
    if (scanWrap.nextSibling) end.insertBefore(wrap, scanWrap.nextSibling);
    else end.appendChild(wrap);
  }
  else end.prepend(wrap);
}

// Helper used by renderGlobeDropdown internals (defined globally so it survives
// re-renders of the dropdown).
function refreshGlobeBadgeIfReady() {
  try {
    if (typeof window.__nspRefreshGlobeBadge === 'function') window.__nspRefreshGlobeBadge();
  } catch(e) {}
}

// When the user picks a market:
//   1) IMMEDIATELY save flag to localStorage (synchronous — no race)
//   2) Set cookie via SW (async, fire-and-forget)
//   3) Reload to /feed/trending of that country (immediate)
//   4) After reload, bundle reads localStorage flag → auto-triggers SCAN
//
// localStorage is used instead of chrome.storage because chrome.storage is
// async and would cause race conditions with location.href.
function syncYouTubePrefCookieFromPrefs() {
  console.log('[NSP] syncYouTubePrefCookieFromPrefs called');
  try {
    var prefs = NspScanPrefs.get();
    var meta = NSP_MARKET_META[prefs.market];
    var gl = (meta && meta.gl) || '';
    var hl = (meta && meta.hl) || '';
    console.log('[NSP] market:', prefs.market, 'gl:', gl, 'hl:', hl);

    // Fire-and-forget cookie set (background)
    try { sendRuntimeMessage({ type: 'NSP_SET_YT_COOKIE', gl: gl, hl: hl }).catch(function() {}); } catch(e) {}

    // Global picked → just clean badge, no reload/scan
    if (!gl || !hl) {
      refreshGlobeBadgeIfReady();
      try { localStorage.removeItem('nsp_auto_scan_pending'); } catch(e) {}
      return;
    }

    // 1) SAVE FLAG SYNCHRONOUSLY in localStorage (no race condition with reload)
    try {
      var flagData = JSON.stringify({ market: prefs.market, language: prefs.language, depth: prefs.depth, gl: gl, hl: hl, ts: Date.now() });
      localStorage.setItem('nsp_auto_scan_pending', flagData);
      console.log('[NSP] flag saved to localStorage:', flagData);
    } catch(e) { console.error('[NSP] localStorage save failed:', e); }

    // 2) Show switch toast IMMEDIATELY (so user sees something happen)
    showMarketSwitchToast(meta);

    // 3) Reload after a short delay (gives the toast a moment to render)
    setTimeout(function() {
      try {
        if (typeof location !== 'undefined' && /(^|\.)youtube\.com$/.test(location.hostname)) {
          var targetUrl = 'https://www.youtube.com/feed/trending?hl=' + encodeURIComponent(hl) +
            '&gl=' + encodeURIComponent(gl) + '&persist_hl=1&persist_gl=1';
          console.log('[NSP] reloading to:', targetUrl);
          location.href = targetUrl;
        }
      } catch(e) { console.error('[NSP] reload error:', e); }
    }, 450);
  } catch(e) { console.error('[NSP] sync error:', e); }
}

