// Auto-scan trigger after market change reload.
// Reads `nsp_auto_scan_pending` from localStorage (SYNC, no race conditions).
// If found and fresh, waits for showScanReport to be available, then fires it
// with the stealth flag active.
(function checkAutoScanAfterReload() {
  var dispatched = false;
  function tryDispatch() {
    if (dispatched) return;
    try {
      var raw = localStorage.getItem('nsp_auto_scan_pending');
      if (!raw) return;
      var flag;
      try { flag = JSON.parse(raw); } catch(e) { localStorage.removeItem('nsp_auto_scan_pending'); return; }
      if (!flag || !flag.ts) return;
      if (Date.now() - flag.ts > 60000) {
        localStorage.removeItem('nsp_auto_scan_pending');
        console.log('[NSP] auto-scan flag expired');
        return;
      }
      dispatched = true;
      localStorage.removeItem('nsp_auto_scan_pending');
      console.log('[NSP] auto-scan flag found in localStorage:', flag);

      function waitForReady(attempts) {
        attempts = attempts || 0;
        var maxAttempts = 60; // 60 * 400ms = 24s

        var fnReady = (typeof showScanReport === 'function');
        var btnReady = !!document.getElementById('nsp-batman-scan-btn');

        if (fnReady && (btnReady || attempts >= 15)) {
          // Activate stealth flag (used by runAshlyVPreparedScan + finalize)
          window._nspStealthCountryScan = {
            active: true,
            market: flag.market,
            language: flag.language || getAshlyVLanguageForMarket(flag.market) || 'auto',
            depth: flag.depth || 'balanced',
            gl: flag.gl,
            hl: flag.hl,
            startTs: Date.now()
          };
          console.log('[NSP] dispatching showScanReport with stealth flag');
          try { showAutoScanStartingToast(flag); } catch(e) {}
          setTimeout(function() {
            try {
              var linkedPrefs = normalizeLinkedScanPrefs(NspScanPrefs.get(), {
                market: flag.market || 'global',
                language: flag.language || getAshlyVLanguageForMarket(flag.market) || 'auto',
                depth: flag.depth || NspScanPrefs.get().depth || 'balanced'
              });
              NspScanPrefs.ensureLoaded(true)
                .then(function() { return NspScanPrefs.set(linkedPrefs); })
                .catch(function() { return linkedPrefs; })
                .then(function() {
                  refreshGlobeBadgeIfReady();
                  if (typeof showScanReport === 'function') {
                    showScanReport();
                  } else {
                    var btn = document.getElementById('nsp-batman-scan-btn');
                    if (btn) btn.click();
                  }
                });
            } catch(eDispatch) {
              console.error('[NSP] dispatch error:', eDispatch);
              try { updateStealthToast('error', { msg: eDispatch.message || 'fail' }); } catch(e) {}
            }
          }, 700);
          return;
        }

        if (attempts >= maxAttempts) {
          console.warn('[NSP] auto-scan timeout — fnReady:', fnReady, 'btnReady:', btnReady);
          try { updateStealthToast('error', { msg: 'SCAN no disponible' }); } catch(e) {}
          return;
        }
        setTimeout(function() { waitForReady(attempts + 1); }, 400);
      }
      // Initial delay so YT renders
      setTimeout(function() { waitForReady(0); }, 1500);
    } catch(e) { console.error('[NSP] check auto-scan error:', e); }
  }

  // Multi-trigger: run on whatever fires first
  if (document.readyState === 'complete' || document.readyState === 'interactive') {
    tryDispatch();
  } else {
    document.addEventListener('DOMContentLoaded', tryDispatch, { once: true });
  }
  try {
    document.addEventListener('yt-navigate-finish', function() {
      setTimeout(tryDispatch, 500);
    }, { once: true });
  } catch(e) {}
  // Final safety: try again after 3s no matter what (in case events didn't fire)
  setTimeout(tryDispatch, 3000);
})();

