var CHANNEL_ANALYSIS_STOPWORDS = {
  the:1,a:1,an:1,and:1,for:1,with:1,from:1,that:1,this:1,into:1,your:1,about:1,what:1,when:1,where:1,
  el:1,la:1,los:1,las:1,una:1,uno:1,con:1,para:1,como:1,que:1,del:1,por:1,sobre:1,desde:1,hasta:1
};

function sleepMs(ms) {
  return new Promise(function(resolve) { setTimeout(resolve, ms || 0); });
}

function extractAnalysisKeywords(scored, limit) {
  var counts = {};
  (scored || []).forEach(function(s) {
    (normalizeAshlyVResultTitle(s.title || '').split(' ') || []).forEach(function(w) {
      if (!w || w.length < 4 || CHANNEL_ANALYSIS_STOPWORDS[w] || /^\d+$/.test(w)) return;
      counts[w] = (counts[w] || 0) + 1;
    });
  });
  var sortable = [];
  for (var k in counts) sortable.push({ word: k, count: counts[k] });
  sortable.sort(function(a, b) { return b.count - a.count; });
  return sortable.slice(0, limit || 5).map(function(item) { return item.word; });
}

