function inferExactChannelNiche(scored, description, channelName, language) {
  var titles = (scored || []).map(function(s) { return String((s && s.title) || ''); });
  var keywords = extractAnalysisKeywords(scored, 8);
  var langKey = language === 'es' ? 'es' : 'en';
  var best = null;

  EXACT_CHANNEL_NICHE_META.forEach(function(meta) {
    var score = 0;
    titles.forEach(function(title) { if (meta.re.test(title)) score += 4; });
    if (meta.re.test(description || '')) score += 3;
    if (meta.re.test(channelName || '')) score += 1;
    keywords.forEach(function(keyword) { if (meta.re.test(keyword)) score += 1; });
    if (!best || score > best.score) best = { meta: meta, score: score };
  });

  var fallbackLabel = detectNicheLabel([description || '', channelName || '', titles.slice(0, 3).join(' ')].join(' '));
  var merged = [];
  function pushTerm(term) {
    term = String(term || '').replace(/\s+/g, ' ').trim();
    if (!term) return;
    var key = term.toLowerCase();
    if (merged.indexOf(key) !== -1) return;
    merged.push(key);
  }

  if (best && best.score >= 4) {
    (best.meta.queryTerms[langKey] || []).forEach(pushTerm);
    keywords.forEach(pushTerm);
    return {
      label: best.meta.label,
      query: merged.slice(0, 4).join(' '),
      keywords: keywords,
      score: best.score
    };
  }

  keywords.forEach(pushTerm);
  if (!merged.length && fallbackLabel) pushTerm(fallbackLabel);
  return {
    label: fallbackLabel || 'General',
    query: merged.slice(0, 4).join(' ') || 'youtube niche',
    keywords: keywords,
    score: 0
  };
}

function extractChannelDeepMeta() {
  var out = { description: 'unknown', handle: 'unknown', videoCount: null, videoCountText: 'unknown' };
  try {
    var meta = window.ytInitialData && window.ytInitialData.metadata && window.ytInitialData.metadata.channelMetadataRenderer;
    if (meta) {
      if (meta.description) out.description = meta.description;
      if (meta.vanityChannelUrl) {
        var handleMatch = String(meta.vanityChannelUrl).match(/youtube\.com\/(@[^/?#]+)/i);
        if (handleMatch) out.handle = handleMatch[1];
      }
    }
  } catch(e) {}
  if (out.handle === 'unknown') {
    var pathHandle = location.pathname.match(/\/(@[^/?#]+)/);
    if (pathHandle) out.handle = pathHandle[1];
  }
  try {
    var descNode = document.querySelector('#description, ytd-about-channel-renderer #description, yt-attributed-string');
    if (out.description === 'unknown' && descNode) {
      var txt = (descNode.textContent || '').trim();
      if (txt) out.description = txt;
    }
  } catch(e) {}
  try {
    var raw = (document.body && document.body.textContent) || '';
    var vm = raw.match(/(\d[\d.,]*)\s+(videos|video)/i);
    if (vm) {
      out.videoCountText = vm[0];
      out.videoCount = pViews(vm[1]);
    }
  } catch(e) {}
  return out;
}

function extractAnalysisVideoFromCard(card) {
  try {
    if (!card) return null;
    var vidInfo = getVidId(card);
    var ytEntry = vidInfo && vidInfo.id ? getYtMap()[vidInfo.id] : null;
    var domData = getDomViews(card) || null;
    var titleNode = getVideoTitleNode(card);
    var title = ((titleNode && (titleNode.getAttribute('title') || titleNode.textContent)) || '').trim();
    if (!title || title.length < 3) return null;
    var views = (ytEntry && ytEntry.views) || (domData && domData.views) || 0;
    var hoursOld = ytEntry && ytEntry.hoursOld != null ? ytEntry.hoursOld : (domData ? domData.hoursOld : null);
    if (hoursOld == null || !isFinite(hoursOld)) {
      var domAge = getDomAge(card) || parseAgeFromText((card.textContent || ''));
      if (domAge) hoursOld = domAge.hoursOld;
    }
    if (!views || views < 1) return null;
    var durationSecs = 0;
    try {
      if (ytEntry && ytEntry.lengthText) durationSecs = parseDurationSecs(ytEntry.lengthText);
      if (!durationSecs) {
        var timeEl = card.querySelector('ytd-thumbnail-overlay-time-status-renderer span, #text.ytd-thumbnail-overlay-time-status-renderer');
        if (timeEl) durationSecs = parseDurationSecs(timeEl.textContent);
      }
    } catch(e) {}
    var sc = calcScore(views, hoursOld, !!(vidInfo && vidInfo.isShort), title, durationSecs);
    if (!sc) return null;
    sc.hoursOld = hoursOld;
    sc.publishedTimeText = (ytEntry && ytEntry.timeText) || (domData && domData.timeText) || '';
    sc.timeText = sc.publishedTimeText || '';
    sc.ageText = sc.publishedTimeText || '';
    sc.durationSecs = durationSecs;
    sc.title = title;
    sc.vidId = vidInfo ? vidInfo.id : '';
    sc.views = views;
    sc.subs = getDomSubs(card);
    if (sc.subs > 0) sc.os += calculateOutlierBonus(views, sc.subs);
    if (ytEntry) {
      sc.channelUrl = ytEntry.channelUrl || '';
      sc.channelKey = ytEntry.channelKey || '';
      sc.channelId = ytEntry.channelId || '';
      sc.channelName = ytEntry.channelName || '';
    }
    var chInfo = getChannelFromCard(card, vidInfo);
    if (chInfo) {
      if (!sc.channelUrl && chInfo.channelUrl) sc.channelUrl = chInfo.channelUrl;
      if (!sc.channelKey && chInfo.channelKey) sc.channelKey = chInfo.channelKey;
      if (!sc.channelId && chInfo.channelId) sc.channelId = chInfo.channelId;
      if (!sc.channelName && chInfo.name) sc.channelName = chInfo.name;
    }
    return sc;
  } catch(e) { return null; }
}

function collectAshlyVVisibleCardFallbackResults(limit) {
  limit = Math.max(1, Number(limit || ASHLYV_MAX_UNIQUE_SCAN || 300));
  var out = [];
  var seen = {};
  var cards = [];
  try { cards = Array.prototype.slice.call(document.querySelectorAll(SEL)); } catch(eCards) { cards = []; }
  for (var i = 0; i < cards.length && out.length < limit; i++) {
    var sc = extractAnalysisVideoFromCard(cards[i]);
    if (!sc) continue;
    var key = getAshlyVDedupeKeyFromSc(sc) || sc.vidId || normalizeAshlyVResultTitle(sc.title || '');
    if (!key || seen[key]) continue;
    seen[key] = true;
    out.push({
      card: cards[i],
      domElement: cards[i],
      sc: sc,
      videoId: sc.videoId || sc.vidId || '',
      title: sc.title || '',
      channelName: sc.channelName || sc.channelHandle || '',
      channelId: sc.channelId || sc.channelKey || sc.channelUrl || '',
      url: sc.url || sc.videoUrl || (sc.vidId ? ('https://www.youtube.com/watch?v=' + encodeURIComponent(sc.vidId)) : ''),
      dedupeKey: key,
      normalizedTitleBase: getAshlyVNormalizedTitleBase(sc.title || ''),
      globalDiscoveryOrder: 200000 + i,
      _cardIndex: 200000 + i
    });
  }
  if (out.length) console.log('[ASHLYV] Visible DOM fallback collected:', out.length, 'from cards:', cards.length);
  return out;
}

async function collectDeepChannelSample() {
  var profile = getDepthProfile('channel');
  var startY = window.scrollY || 0;
  var sample = [];
  var seen = {};
  function collect() {
    var cards = Array.prototype.slice.call(document.querySelectorAll(SEL + ', ytd-rich-grid-media'));
    for (var i = 0; i < cards.length && sample.length < profile.maxCards; i++) {
      var sc = extractAnalysisVideoFromCard(cards[i]);
      if (!sc) continue;
      var key = sc.vidId || normalizeAshlyVResultTitle(sc.title || '');
      if (!key || seen[key]) continue;
      seen[key] = true;
      sample.push(sc);
    }
  }
  collect();
  for (var step = 0; step < profile.scrollSteps && sample.length < profile.maxCards; step++) {
    try { window.scrollBy({ top: Math.max(900, Math.round(window.innerHeight * 1.25)), behavior: 'instant' }); }
    catch(e) { window.scrollBy(0, Math.max(900, Math.round(window.innerHeight * 1.25))); }
    await sleepMs(profile.pauseMs);
    collect();
  }
  try { window.scrollTo({ top: startY, behavior: 'instant' }); } catch(e) { window.scrollTo(0, startY); }
  return sample.slice(0, profile.maxCards);
}

function inferDeepTitlePattern(scored) {
  if (!scored || !scored.length) return 'unknown';
  var avgLen = 0, numbers = 0, separators = 0, questions = 0;
  scored.forEach(function(s) {
    var t = s.title || '';
    avgLen += t.length;
    if (/\d/.test(t)) numbers++;
    if (/[:|]/.test(t)) separators++;
    if (/\?/.test(t)) questions++;
  });
  var parts = [];
  if (numbers / scored.length >= 0.35) parts.push('numbers / list hooks');
  if (separators / scored.length >= 0.35) parts.push('subtitle separators');
  if (questions / scored.length >= 0.25) parts.push('question-led');
  parts.push((Math.round(avgLen / scored.length) >= 55) ? 'long descriptive titles' : 'compact direct titles');
  var kws = extractAnalysisKeywords(scored, 4);
  if (kws.length) parts.push('keywords: ' + kws.join(', '));
  return parts.join(' | ');
}

function inferDeepThumbnailPattern(scored, niche) {
  if (!scored || !scored.length) return 'unknown';
  var longForm = scored.filter(function(s) { return !s.isShort && (s.durationSecs || 0) >= 480; }).length;
  var numbered = scored.filter(function(s) { return /\d/.test(s.title || ''); }).length;
  if (longForm / scored.length >= 0.65 && /Historia|Ciencia|Naturaleza|Psicologia|Misterio/.test(niche || '')) return 'Likely cinematic / illustrated documentary covers (heuristic)';
  if (numbered / scored.length >= 0.4) return 'Likely bold-text list / ranking covers (heuristic)';
  if (scored.filter(function(s) { return s.isShort; }).length / scored.length >= 0.5) return 'Mixed / short-driven visual system';
  return 'unknown from visible DOM only';
}

function inferDeepTone(scored, description) {
  var text = ((description || '') + ' ' + (scored || []).map(function(s) { return s.title || ''; }).join(' ')).toLowerCase();
  if (/hvac|house|home|repair|replace|install|fix|cooling|heating|diy|plumbing|electrical|thermostat|heat pump|mini split|duct|ventilation/i.test(text)) return 'practical / problem-solution';
  if (/mystery|dark|forbidden|legend|myth|cryptid|unexplained|ancient/i.test(text)) return 'mysterious / dramatic narration';
  if (/how to|explained|guide|tips|learn|tutorial/i.test(text)) return 'educational / explainer';
  if (/stoic|mindset|psychology|discipline|habit/i.test(text)) return 'reflective / self-improvement';
  if (/finance|business|wealth|invest|money/i.test(text)) return 'practical / authoritative';
  if (/documentary|history|science|nature/i.test(text)) return 'documentary / informative';
  return 'unknown';
}

function inferDeepFormat(scored, description) {
  var text = ((description || '') + ' ' + (scored || []).map(function(s) { return s.title || ''; }).join(' ')).toLowerCase();
  var avgDur = calcAvgDuration(scored || []);
  if (/hvac|repair|replace|install|fix|diy|home improvement|plumbing|electrical|thermostat|heat pump|mini split|duct|ventilation/i.test(text)) return 'problem-solution / diy';
  if (/story|stories|legend|myth|epic|tale/i.test(text)) return 'storytelling';
  if (/documentary|history|historical|nature|science/i.test(text) && avgDur >= 600) return 'documentary';
  if (/explained|how to|guide|lesson|tutorial/i.test(text)) return 'explainer / teaching';
  if (/crime|mystery|dark|forbidden|horror/i.test(text)) return 'dramatic narration';
  if (/commentary|reaction|opinion/i.test(text)) return 'commentary';
  return avgDur >= 600 ? 'long-form narration' : 'unknown';
}

function inferDeepSubniches(scored, description) {
  var text = ((description || '') + ' ' + (scored || []).map(function(s) { return s.title || ''; }).join(' ')).toLowerCase();
  var rules = [
    { re:/hvac|furnace|air conditioner|air conditioning|heat pump|mini split|duct|vent|thermostat|boiler|wall heater|heating|cooling|ventilation/i, label:'hvac / home systems' },
    { re:/plumbing|electrical|repair|replace|install|wall|roof|window|house|home|garage|insulation|tool/i, label:'home repair / diy' },
    { re:/myth|mythology|legend|god|gods|epic|folklore/i, label:'mythology / folklore' },
    { re:/ancient|empire|roman|greek|viking|medieval|mesopotamia|pharaoh/i, label:'ancient civilizations' },
    { re:/crime|murder|killer|investigation|case/i, label:'true crime' },
    { re:/survival|prepper|wilderness|off grid|homestead/i, label:'survival / preparedness' },
    { re:/finance|wealth|money|invest|budget|business/i, label:'finance / wealth' },
    { re:/psychology|stoic|mindset|habit|discipline/i, label:'psychology / mindset' },
    { re:/space|cosmos|planet|universe|nasa/i, label:'space / astronomy' },
    { re:/nature|animal|wildlife|ocean|forest/i, label:'nature / wildlife' }
  ];
  var out = [];
  rules.forEach(function(rule) { if (rule.re.test(text) && out.indexOf(rule.label) === -1) out.push(rule.label); });
  if (!out.length) out = extractAnalysisKeywords(scored, 3);
  return out.slice(0, 4);
}

function inferDeepAudience(niche, tone, language) {
  if (/Finanzas|Negocios|IA y Automatizacion|Tecnologia/.test(niche || '')) return 'adults seeking practical knowledge / ROI content';
  if (/HVAC y Sistemas del Hogar|Hogar y DIY|Supervivencia/.test(niche || '') || /problem-solution/.test(tone || '')) return 'homeowners / practical viewers looking for direct fixes';
  if (/Historia|Ciencia|Naturaleza|Misterio/.test(niche || '')) return 'curiosity-driven viewers who enjoy long-form learning';
  if (/Psicologia/.test(niche || '') || /self-improvement/.test(tone || '')) return 'self-improvement / reflective audience';
  if (language && NSP_LANGUAGE_META[language]) return 'viewers comfortable with ' + NSP_LANGUAGE_META[language].label;
  return 'unknown';
}

function estimateDeepMonetization(niche, scored, description) {
  var text = ((description || '') + ' ' + (scored || []).map(function(s) { return s.title || ''; }).join(' ')).toLowerCase();
  var score = 62;
  if (/Finanzas|Negocios|IA y Automatizacion|Tecnologia/.test(niche || '')) score += 12;
  if (/Historia|Ciencia|Naturaleza|Psicologia/.test(niche || '')) score += 6;
  if (/crypto|casino|gambling|adult|nsfw|blood|killer|violent/i.test(text)) score -= 18;
  if (/crime|horror|war|dark/i.test(text)) score -= 8;
  score = Math.max(15, Math.min(95, score));
  return { score: score, label: score >= 75 ? 'high / advertiser-friendly' : score >= 55 ? 'moderate / execution-sensitive' : 'caution / sensitive topic mix' };
}

function buildDeepExpansionAnglesES(niche, subniches) {
  var first = subniches[0] || niche || 'este nicho';
  return [
    'Versiones de ' + first + ' con enfoque explicado en 10 minutos',
    'Series por era / caso / subtema dentro de ' + first,
    'Compilados faceless premium con thumbnails mas claros y ganchos mas directos'
  ];
}

function buildDeepExpansionAnglesEN(niche, subniches) {
  var first = subniches[0] || niche || 'this niche';
  return [
    first + ' explained in concise episodic format',
    'Series-based expansion by subtopic / era / case',
    'Higher-RPM spin with cleaner thumbnails and stronger hooks'
  ];
}

function analyzeChannelDeep(ch, scored) {
  var meta = extractChannelDeepMeta();
  var description = meta.description || 'unknown';
  var language = detectTextLanguage((description || '') + ' ' + (scored || []).map(function(s) { return s.title || ''; }).join(' '));
  var nicheMeta = inferExactChannelNiche(scored, description, ch.name || '', language);
  var niche = nicheMeta.label || detectNicheLabel((description || '') + ' ' + (ch.name || '') + ' ' + ((scored[0] && scored[0].title) || ''));
  var subniches = inferDeepSubniches(scored, description);
  var tone = inferDeepTone(scored, description);
  var formatType = inferDeepFormat(scored, description);
  var titlePattern = inferDeepTitlePattern(scored);
  var thumbnailPattern = inferDeepThumbnailPattern(scored, niche);
  var avgDurationSecs = calcAvgDuration(scored || []);
  var uploadDays = calcUploadFreq(scored || []);
  var uploadCadence = uploadDays ? ('~cada ' + uploadDays + ' dias') : 'unknown';
  var cadenceScore = uploadDays ? Math.max(28, Math.min(95, 92 - Math.abs(uploadDays - 4) * 8)) : 38;
  var facelessSum = 0, facelessN = 0;
  (scored || []).forEach(function(s) {
    try {
      var a = AshlyVFaceless && AshlyVFaceless.analyzeItem ? AshlyVFaceless.analyzeItem({ sc: s }) : null;
      if (a && a.facelessScore != null) { facelessSum += a.facelessScore; facelessN++; }
    } catch(e) {}
  });
  var facelessScore = facelessN ? Math.round(facelessSum / facelessN) : (/documentary|storytelling|dramatic narration|explainer/i.test(formatType) ? 66 : 50);
  var repeatabilityScore = Math.max(20, Math.min(98, Math.round(facelessScore * 0.35 + cadenceScore * 0.15 + (extractAnalysisKeywords(scored, 4).length * 8) + (/unknown/.test(formatType) ? 8 : 18))));
  var copyabilityScore = Math.max(20, Math.min(99, Math.round(repeatabilityScore * 0.58 + facelessScore * 0.28 + (/unknown/.test(thumbnailPattern) ? 6 : 14))));
  var monetization = estimateDeepMonetization(niche, scored, description);
  var topVideo = null;
  (scored || []).forEach(function(s) { if (!topVideo || s.vph > topVideo.vph) topVideo = s; });
  return {
    channel: { name: ch.name || 'unknown', handle: meta.handle || 'unknown', description: description || 'unknown', subsText: ch.subs ? fmtN(ch.subs) : 'unknown', videoCountText: meta.videoCountText || 'unknown', sampleCount: (scored || []).length },
    niche: niche || 'General',
    subniches: subniches.length ? subniches : ['unknown'],
    language: language,
    facelessScore: facelessScore,
    repeatabilityScore: repeatabilityScore,
    copyabilityScore: copyabilityScore,
    tone: tone || 'unknown',
    formatType: formatType || 'unknown',
    titlePattern: titlePattern || 'unknown',
    thumbnailPattern: thumbnailPattern || 'unknown',
    nicheSearchQuery: nicheMeta.query || niche || 'youtube niche',
    nicheKeywords: nicheMeta.keywords || [],
    uploadCadence: uploadCadence,
    avgDurationSecs: avgDurationSecs,
    targetAudience: inferDeepAudience(niche, tone, language),
    styleSummary: [formatType || 'unknown', tone || 'unknown', titlePattern || 'unknown'].join(' | '),
    monetization: monetization,
    expansionES: buildDeepExpansionAnglesES(niche, subniches),
    expansionEN: buildDeepExpansionAnglesEN(niche, subniches),
    topVideo: topVideo,
    recentVideos: (scored || []).slice().sort(function(a, b) { return (a.hoursOld || 999999) - (b.hoursOld || 999999); }).slice(0, 6)
  };
}

